(window.__BOOKS=window.__BOOKS||{})["e_heracles"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Мегара, при ней три малолетних сына</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор фиванских старцев</span>"],["person","<span class=\"pn\">Лик, при нем стража</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Ирида</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Лисса</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"tesey\">Тесей</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"gerakl\">Геракл</span></span> <span class=\"act-no\">(I)</span>"],["act","Пролог","a1",""],["sd","Задняя декорация представляет стену Гераклова дворца в Фивах, посредине большие ворота. Перед дворцом, на площади, большой каменный алтарь Зевса Спасителя. На его ступенях сидят <span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>, <span class=\"ch\" data-ch=\"megara\">Мегара</span> и дети."],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Кому неведом муж, который с Зевсом",0,1,0,0],["v","Любовь жены делил, <span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>",0,1,0,0],["v","Из Аргоса, Алкид и внук Нерсея,",0,1,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> знаменитого отец?",0,2,0,0],["v","Да, родом я из Аргоса, но в Фивах",0,3,0,0],["v","Средь поколенья горсти земнородных,<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,4,0,0],["v","Что в битвах уцелели из посева,",0,5,0,0],["v","Мне довелося жить. Из крови спартов",0,6,0,0],["v","Произошел и Менекеев сын,",0,7,0,0],["v","Отец вот этой женщины, <span class=\"ch\" data-ch=\"megara\">Мегары</span>.",0,8,0,0],["v","Давно ли, кажется, под звуки флейты,",0,9,1,0],["v","Под звуки гимна брачного, который",0,10,0,1],["v","Кадмейцы пели, в этот царский дом",0,10,0,0],["v","Привел ее великий внук Алкея?",0,11,0,0],["v","Он с нами жил недолго: и <span class=\"ch\" data-ch=\"megara\">Мегару</span>,",0,12,0,0],["v","И новую родню покинув, весь",0,12,0,0],["v","Горел желаньем он — в далекий Аргос",0,13,0,0],["v","Уйти и овладеть стенами града",0,14,0,0],["v","Киклопов, из которых был я изгнан,",0,14,0,0],["v","Запятнанный Электриона кровью.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a><a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,15,0,0],["v","Чтоб смыть с отца позорное пятно",0,16,1,0],["v","И воротить себе отцовский город,",0,16,0,0],["v","Сын заплатил не дешево и подвиг",0,17,0,0],["v","Для Еврисфея справил не один:",0,18,0,0],["v","Всю землю он очистил от чудовищ…",0,18,0,0],["v","Безумием ли был <span class=\"ch\" data-ch=\"gerakl\">Геракл</span> охвачен,",0,19,0,0],["v","От Геры насланным, или к тому",0,20,0,1],["v","Его судьба вела, — не знаю, право.",0,20,0,0],["v","Теперь, когда, могучий, он осилил",0,21,0,0],["v","Все тяжкие труды, в жерло Тенара<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,22,0,0],["v","Его услали, чтоб из царства мрака",0,23,0,0],["v","На свет он вывел пса о трех телах;",0,24,0,0],["v","Герой пошел и больше не вернулся…",0,25,0,0],["v","Я старое преданье здесь слыхал,",0,26,1,0],["v","Что в семивратных Фивах был когда-то",0,27,0,0],["v","Царем могучий <span class=\"ch\" data-ch=\"lik\">Лик</span>, супруг Диркеи,",0,28,0,0],["v","Которого сменили близнецы,",0,29,0,0],["v","Зет с Амфионом, порожденье Зевса,",0,30,0,1],["v","Владельцы белоснежных лошадей.",0,30,0,0],["v","Так вот, потомок <span class=\"ch\" data-ch=\"lik\">Лика</span>, не кадмеец,",0,31,0,0],["v","А выходец с Евбеи, тоже <span class=\"ch\" data-ch=\"lik\">Лик</span>,",0,32,0,0],["v","Здесь только что убил царя Креонта",0,33,0,0],["v","И мятежом истерзанные Фивы<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,34,0,0],["v","Своей тиранской власти подчинил.",0,35,0,0],["v","Мы, родичи Креонтовы, конечно,",0,35,1,0],["v","В опале: новый царь замыслил кровью",0,36,0,0],["v","Его детей смыть пролитую кровь…",0,37,0,0],["v","Пока отца земные недра кроют,",0,38,0,0],["v","Он ищет погубить его вдову",0,39,0,0],["v","И сыновей, чтоб, возмужав, за деда",0,40,0,1],["v","Не стали мстить, — да, кстати, и меня:",0,41,0,0],["v","Должно быть, и старик тирану страшен.",0,42,0,0],["v","А между тем, сходя в юдоль теней,",0,43,0,0],["v","Герой мне отдал сыновей в опеку,",0,44,0,0],["v","Жену и дом велел мне сберегать.",0,45,0,0],["v","Что ж было делать мне? Я под защиту",0,46,0,0],["v","Зевеса всю семью сюда привел.",0,47,0,0],["v","И вот у алтаря мы приютились,",0,48,0,0],["v","Что некогда воздвиг мой славный сын,",0,49,0,0],["v","С победою вернувшись от минийцев.<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,50,0,1],["v","Вы видите: без хлеба, без воды,",0,50,0,0],["v","Нагие и босые, на холодной",0,51,0,0],["v","Земле мы смерти ждем; а перед нами",0,52,0,0],["v","Наш царский дом, забит и опечатан.",0,53,0,0],["v","Спасенья не видать, и те друзья,",0,53,0,0],["v","Что выручить могли бы нас, не стоят",0,54,0,0],["v","Названия друзей, а верные и сил",0,55,0,0],["v","Не соберут помочь нам — сами старцы.",0,56,0,0],["v","Вот каковы несчастья — для людей!",0,56,0,0],["v","Да не познает их, кто хоть немного",0,57,0,0],["v","Ко мне питает жалости… а впрочем,",0,58,0,0],["v","Узнать друзей помогут лишь они.",0,59,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["dir","долго смотрит на <span class=\"ch\" data-ch=\"amfitrion\">Амфитриона</span>"],["v","Подумать, что и ты, отец, когда-то",0,60,0,1],["v","Был славный вождь, что во главе дружин",0,60,0,0],["v","Фиванских ты умел разрушить стены",0,61,0,0],["v","Тафийские… О, как неясны смертным",0,62,0,0],["v","Богов предначертанья! Разве счастье<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,63,0,0],["v","Под отчим кровом мне не улыбалось?",0,64,0,0],["v","Царевной я жила, довольством, блеском",0,65,0,0],["v","И завистью людской окружена;",0,65,0,0],["v","Отца семьей благословили боги…",0,66,0,0],["v","А мой блестящий брак с твоим <span class=\"ch\" data-ch=\"gerakl\">Гераклом</span>?..",0,67,0,0],["v","Где ж это счастье? Сгибло, стало прахом,",0,68,0,0],["v","И только смерть теперь в глаза глядит",0,69,0,0],["v","Тебе, старик, и мне, и Гераклидам,",0,70,0,1],["v","Моим несчастным детям. А уж я ль",0,70,0,0],["v","Птенцов неоперившихся под крылья",0,71,0,0],["v","Не прятала? Поверишь, поминутно",0,72,0,0],["v","Они меня расспросами терзают:",0,73,0,0],["v","\"Ах, мама, где отец? Чего не едет?",0,73,0,0],["v","Когда ж он будет с нами?\" Иль бегут",0,74,0,0],["v","Его искать повсюду, точно в прятки",0,75,0,0],["v","Играет с ними бедный их отец.",0,76,0,0],["v","Придумаю ль угомонить их сказкой…",0,76,0,0],["v","Куда там! Стоит двери заскрипеть,",0,77,0,0],["v","Все, как один: «Отец, отец приехал!» —",0,78,0,0],["v","Бегут его колени обнимать…",0,79,0,0],["sd","(Гладит детей, которые к ней прижимаются, потом, помолчав, к <span class=\"ch\" data-ch=\"amfitrion\">Амфитриону</span>.)"],["v","Ну что же, старец, может быть, придумал",0,80,0,1],["v","Ты что-нибудь? О, если б хоть не выход,",0,80,0,0],["v","Лишь слабый луч спасенья нам увидеть!",0,81,0,0],["v","Бежать из города? Повсюду стража,",0,82,0,0],["v","Ворота на запоре… А на дружбу",0,83,0,0],["v","Надеюсь я не более, чем ты…",0,84,0,0],["v","Но говори, отец, не бойся словом",0,85,0,0],["v","Мне неизбежность смерти подтвердить!",0,85,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Дитя мое! Не подобают старцу",0,86,0,0],["v","Несбыточные планы и гаданья.",0,87,0,0],["v","Мы слабы, но зачем же нам спешить?",0,88,0,0],["v","Ведь умереть, Мегара, мы успеем.",0,89,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Что ж, горя мало или жить так сладко?",0,90,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Да, сладко и надеяться и жить.",0,90,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Надеяться!.. Но где ж она, надежда?",0,91,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Переживи недуг — и будешь здрав.",0,92,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Переживи!.. Измучит неизвестность…",0,93,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Дитя мое… а если среди зол,",0,94,0,0],["v","Объявших нас, счастливый ветер снова",0,95,0,0],["v","Подует нам? Супруг твой, сын мой милый,",0,96,0,0],["v","Нежданный к нам вернется?.. Нет, Мегара,",0,97,0,0],["v","Нет, дочь моя: ты — мать, так будь бодрей!",0,98,0,0],["v","Утри глаза малюткам и старайся",0,99,0,0],["v","Прогнать их детский страх веселой сказкой.",0,100,0,1],["v","Поверь, Мегара, что и в жизни смерч,",0,100,0,0],["v","Как в поле ураган, шумит не вечно:",0,101,0,0],["v","Конец приходит счастью и несчастью…",0,102,0,0],["v","Жизнь движет нас бессменно вверх и вниз,",0,103,0,0],["v","А смелый — тот, кто не утратит веры",0,104,0,0],["v","Средь самых страшных бедствий: только трус",0,105,0,0],["v","Теряет бодрость, выхода не видя…",0,105,0,0],["scene","Явление второе","s2",1,2],["scene","Вступительная песнь хора","s3",1,3],["sd","Старики поднимаются по ступеням на сцену и начинают петь, когда еще большая часть зрителей их не видит; они в венках и поднимаются медленно, опираясь на посохи. Поднявшись, они располагаются по обе стороны алтаря. Корифей становится ближе к алтарю."],["sp","Хор"],["str","Строфа"],["v","Поднимайте меня, ноги слабые,",0,106,0,0],["v","Ко дворцу высокому царскому!",0,107,0,0],["v","Помогай ты мне, посох верный,",0,108,1,0],["v","Добрести до старого друга.",0,109,1,0],["v","Заведу я унылую песню,",0,110,1,1],["v","Поседевшего лебедя песню…",0,110,1,0],["v","Что от прошлого в старце осталось?",0,111,1,0],["v","Точно призрак я, ночью рожденный,",0,112,1,0],["v","Только голоса звук и остался…",0,113,1,0],["v","Но пускай дрожит мое тело,",0,114,1,0],["v","Не угасла в груди моей верность",0,115,1,0],["v","Обездоленным этим сиротам,",0,115,1,0],["v","И соратнику дряхлому верность,",0,116,1,0],["v","И тебе, что из ада супруга,",0,117,1,0],["v","Горемычная мать, вызываешь.",0,118,1,0],["str","Антистрофа"],["v","Поддержите ж меня, ноги слабые,",0,119,0,0],["v","Не дрожите, колени усталые!",0,120,0,1],["v","Я не конь, что крутым подъемом",0,120,1,0],["v","С колесницей тащится в гору.",0,121,1,0],["v","Ты возьми мою руку, товарищ!",0,122,1,0],["v","Если ноги тебе изменяют,",0,122,1,0],["v","За мою придержися одежду!",0,123,1,0],["v","Пусть старик старику помогает.",0,124,1,0],["v","Вспомним время, когда, молодыми,",0,125,1,0],["v","Собирались мы тесной толпою",0,125,1,0],["v","И, щиты со щитами сплотивши,",0,126,1,0],["v","Потрясали мы копьями смело.",0,127,1,0],["v","Мы достойными были сынами",0,127,1,0],["v","Нашей славной в те годы отчизне,",0,128,1,0],["v","Семивратным и царственным Фивам.",0,129,1,0],["str","Эпод"],["v","В глазах у детей <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>",0,130,0,1],["v","Отцовская ярая смелость;",0,130,0,0],["v","Отцовская, видно, и доля",0,131,0,0],["v","Покинутым детям досталась.",0,132,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> должны мы так много,",0,133,0,0],["v","Что ж долга мы детям не платим?",0,134,0,0],["v","Эллада, Эллада, каких",0,135,0,0],["v","Могучих сынов ты теряешь!",0,136,0,0],["v","Каких ты защитников губишь!",0,137,0,0],["sp","Корифей"],["v","Постойте, <span class=\"ch\" data-ch=\"lik\">Лик</span> сюда идет, тиран наш,",0,138,0,0],["v","Сейчас он будет около дворца…",0,139,0,0],["act","Действие первое","a2","I"],["scene","Явление третье","s4",2,4],["sd","Те же и <span class=\"ch\" data-ch=\"lik\">Лик</span> в царской одежде; с ним вооруженная стража. Он приходит с той же стороны, откуда пришел и хор."],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span> и ты, жена <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>!",0,140,0,1],["v","Как господин, я требую от вас, —",0,140,0,0],["v","И, кажется, я вправе это сделать, —",0,141,0,0],["v","Я требую, чтоб вы сказали мне,",0,142,0,0],["v","Чего вы ждете здесь? Зачем влачите",0,142,0,0],["v","У алтаря безрадостную жизнь?",0,143,0,0],["v","Надежда есть у вас какая, что ли?",0,144,0,0],["v","Иль, может быть, вы верите, что мертвый,",0,145,0,0],["v","Сошедший в царство Гадеса, отец",0,145,0,0],["v","Вот этих ребятишек возвратится?",0,146,0,0],["v","Скажите, для чего весь этот плач",0,147,0,0],["v","Пред неизбежной смертью? И зачем",0,147,0,0],["v","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span> хвастливо уверяет,",0,148,0,0],["v","Что с Зевсом он любовь жены делил?",0,149,0,0],["v","А ты, Мегара, будто муж твой — первый",0,150,0,1],["v","Из эллинских героев? Да и удаль",0,150,0,0],["v","Какая же убить змею в болоте",0,151,0,0],["v","Да льва еще в Немее одолеть?",0,152,0,0],["v","И задушил-то даже не руками,",0,153,0,0],["v","Как хвастался, а в петле удавил.",0,154,0,0],["v","Что ж? Я на этом основанье должен",0,155,0,0],["v","Детей <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>, что ли, пощадить?",0,155,0,0],["v","Да что такое ваш <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>, скажите?",0,156,0,0],["v","Чем славу заслужил он? Убивая",0,157,0,0],["v","Зверей… на это точно у него",0,158,0,0],["v","Хватало мужества! Но разве взял он",0,159,0,0],["v","Щит иль копье когда, готовясь к бою?",0,160,0,1],["v","Трусливая стрела — его оружье,",0,160,0,0],["v","Военное искусство — в быстрых пятках.",0,161,0,0],["v","Да может ли, скажите мне, стрелок",0,162,0,0],["v","Из лука храбрым быть? Нет, чтобы мужем",0,162,0,0],["v","Быть истинным, спокойным оком надо,",0,163,0,0],["v","Не выходя из воинских рядов,",0,164,0,0],["v","Следить за копьями врагов, и мускул",0,164,0,0],["v","В твоем лице пусть ни один не дрогнет…",0,165,0,0],["sd","(Обращаясь к корифею.)"],["v","Пожалуй, ты жестокостью корить",0,166,0,0],["v","Меня готов, старик; но не жестокость,",0,166,0,0],["v","Лишь осторожность в действиях моих:",0,167,0,0],["v","Убив Креонта, деда их, не вправе ль",0,168,0,0],["v","Я ожидать, что, возмужав, они",0,168,0,0],["v","Отплатят мне за кровь отца <span class=\"ch\" data-ch=\"megara\">Мегары</span>?",0,169,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Пусть Зевс-отец <span class=\"ch\" data-ch=\"gerakl\">Геракла</span> защитит,",0,170,0,1],["v","А я, старик беспомощный, лишь словом",0,170,0,0],["v","Попробую невежество и дерзость",0,171,0,0],["v","В твоих речах, тиран, разоблачить.",0,172,0,0],["v","Порочить моего <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>, и такой",0,172,0,0],["v","Бессмыслицей порочить!.. Разве кто",0,173,0,0],["v","Разумный трусом назовет <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>?",0,174,0,0],["v","Богов зову в свидетели, богов,",0,175,0,0],["v","Что это и бессмыслица и дерзость.",0,175,0,0],["v","Ту молнию и колесницу ту",0,176,0,0],["v","В свидетели небесную беру я,",0,177,0,0],["v","С которой он Гигантов поражал —<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,177,0,0],["v","Ужасных великанов земнородных, —",0,178,0,0],["v","Стрелы ударом верным, чтоб потом",0,179,0,0],["v","Делить с богами славную победу.",0,180,0,1],["v","А ты, жалчайший из тиранов, можешь",0,180,0,0],["v","Спросить хоть у кентавров, — этих, что ли,",0,181,0,0],["v","Разбойников четвероногих, пусть",0,182,0,0],["v","Тебе укажут первого героя",0,183,0,0],["v","По мужеству, и знай: услышишь имя",0,184,0,0],["v","Тобою трусом названного, — да!",0,185,0,0],["v","Отправься следом на свою Евбею",0,185,0,0],["v","И там спроси: тебе не скажут «<span class=\"ch\" data-ch=\"lik\">Лик</span>»;",0,186,0,0],["v","Не слыть героем <span class=\"ch\" data-ch=\"lik\">Лику</span> и в отчизне!",0,187,0,0],["v","Затем, тиран, ты не хотел признать",0,188,0,0],["v","От лука пользы: слушай и учися!",0,189,0,0],["v","Гоплит — он в вечном рабстве у своих",0,190,0,1],["v","Доспехов: сломится ль копье в сраженье,",0,191,0,0],["v","Он беззащитен; будь с ним рядом трусы,",0,192,0,0],["v","Храбрейший из гоплитов пропадет.",0,193,0,0],["v","Ну, а владелец лука может смело",0,194,0,0],["v","Разить врагов: всегда довольно стрел",0,195,0,0],["v","В его распоряженье для защиты.",0,196,0,0],["v","А выстрел издали, когда врагу",0,197,0,0],["v","Тебя не видно, и, прикрытый, можешь",0,198,0,0],["v","Ты целиться? О Лик, вредить врагам,",0,199,0,0],["v","Не отдавая тела супостату,",0,200,0,1],["v","От случая при этом не завися, —",0,201,0,0],["v","Вот высшее искусство на войне.",0,202,0,0],["v","Скажи мне лучше, царь, чем провинились",0,203,1,0],["v","Перед тобою дети и за что",0,204,0,0],["v","Ты хочешь их казнить? Я понимаю,<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,205,0,0],["v","Положим, что детей героя месть",0,206,0,0],["v","Должна страшить ничтожного тирана.",0,207,0,0],["v","Но неужели ж смелые должны",0,208,0,0],["v","Платить за трусость властелина жизнью?",0,210,0,1],["v","Нет, если был бы справедлив к нам Зевс,",0,210,0,0],["v","То жалкий трус являлся б жертвой смелых.",0,211,0,0],["v","А ты, коли действительно задумал",0,212,0,0],["v","Царить над Фивами, зачем убить",0,212,0,0],["v","Нас хочешь? Ну, отправь в изгнанье, что ли!..",0,213,0,0],["v","Насилье ж даром не проходит, Лик,",0,214,0,0],["v","И стоит счастью тылом повернуться,",0,215,0,0],["v","Чтоб из владыки жертвою ты стал.",0,215,0,0],["v","О город Кадма древнего, у старца",0,216,1,0],["v","Давно упрек на сердце для тебя!",0,217,0,0],["v","Так вот какой наградой отплатили",0,217,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> вы, кадмейцы!.. Позабыть,",0,218,0,0],["v","Что некогда один он ополчился",0,219,0,0],["v","За город на минийцев и свободу",0,220,0,1],["v","Порабощенным Фивам возвратил!",0,220,0,0],["v","А ты, Эллада, разве я молчаньем",0,221,1,0],["v","Могу неблагодарность обойти",0,222,0,0],["v","Столь низкую? Птенцов того <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>,",0,223,0,0],["v","Который море возвратил твоим",0,223,0,0],["v","Сынам и смел с земли чудовищ хищных,",0,224,0,0],["v","Ты оставляешь умирать. Я ждал бы",0,225,0,0],["v","Процессии торжественной с огнями",0,226,0,0],["v","И с копьями победными… Вы, дети",0,226,0,0],["v","Несчастные, Эллада отвернулась",0,227,0,0],["v","От вас и Фивы, и ко мне, ко мне",0,228,0,0],["v","С надеждою вы взоры обратили?",0,229,0,0],["v","Иль вы не знаете, что я лишь звук",0,230,0,1],["v","Речей бессильных, только дряхлый старец?",0,230,0,0],["v","О, если б мне былую юность, длань",0,231,0,0],["v","Могучую, я б эти кудри <span class=\"ch\" data-ch=\"lik\">Лику</span>",0,232,0,0],["v","Своим мечом окрасил в красный цвет,",0,233,0,0],["v","Я за море копьем прогнал бы труса.",0,234,0,0],["sp","Корифей"],["v","Не будь вития, только честен будь,",0,235,0,0],["v","И к мыслям ты подыщешь выраженья.",0,236,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Давай тягаться, старый! Ты меня",0,237,0,0],["v","Рази словами, я ж дойму вас делом.",0,238,0,0],["v","Эй, люди, марш! Одни на Геликон,",0,239,0,0],["v","Другие на Парнас и дровосекам<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,240,0,1],["v","Велите лесу натаскать сюда:",0,241,0,0],["v","Вкруг алтаря вы здесь костер сложите",0,242,0,0],["v","И всех, как есть, сожгите их живьем!",0,243,0,0],["v","Поймут небось, что в Фивах уж не мертвый",0,244,0,0],["v","Царит, а настоящий властный муж.",0,245,0,0],["sd","(К хору.)"],["v","Вы ж, старики, остерегайтесь: если",0,246,0,0],["v","По-прежнему вы станете со мной",0,247,0,0],["v","Здесь спорить, уж не Гераклидов жребий",0,248,0,0],["v","Придется вам оплакивать, а свой.",0,250,0,1],["v","Попомните: я — царь, а вы — мне слуги!",0,250,0,0],["sp","Корифей"],["v","Чего ж вы ждете, спарты? Или вы<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,251,0,0],["v","Забыли доблесть предков земнородных,",0,252,0,0],["v","Тех предков, что когда-то сам Арей",0,253,0,0],["v","Здесь вырастил, посеяв у дракона",0,253,0,0],["v","Из жадных десен вырванные зубы?",0,254,0,0],["v","Скорее все! Вверх посохи, что вам",0,255,0,0],["v","Опорой служат, и тирану череп",0,256,0,0],["v","Раскровените, чужестранцу, трусу",0,256,0,0],["v","Бесправному, что назвался царем",0,257,0,0],["v","И, нищий, завладел наследьем вашим!",0,258,0,0],["v","Не для тебя трудились мы, тиран.",0,259,0,0],["v","Иди разбойничать в свою отчизну!",0,260,0,1],["v","И знай, пока я жив, я не отдам",0,260,0,0],["v","Тебе убить детенышей <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>.",0,261,0,0],["v","Не столь глубоко он лежит, детей",0,262,0,0],["v","Оставив, в мрачной пропасти подземной.",0,263,0,0],["v","Лишь доброе я видел от него,",0,264,0,0],["v","А ты, что разорил мое наследье,",0,265,0,0],["v","Мешаешь мне в тяжелую минуту",0,265,0,0],["v","Геракловым сиротам помогать.",0,266,0,0],["v","Увы, рука, зачем копья ты ищешь?",0,267,0,0],["v","Бессильна ты, и тщетен твой порыв.",0,268,0,0],["v","Терпи, старик, когда тиран кичливый",0,269,0,0],["v","Тебя рабом, ругаясь, назовет…",0,270,0,1],["v","О город! Ты раздорам и вражде",0,271,1,0],["v","Себя расхитить дал. Не то бы разве",0,272,0,0],["v","Мог овладеть тобой какой-то <span class=\"ch\" data-ch=\"lik\">Лик</span>?",0,273,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Благодарю вас, старцы, понимаю",0,274,0,0],["v","Ваш благородный гнев. Но для чего",0,275,0,0],["v","Из-за друзей погибших с властелином",0,276,0,0],["v","Вам ссориться? А ты, Амфитрион,",0,277,0,0],["v","Теперь послушай речь мою, разумно ль",0,278,0,0],["v","Я рассудила. Я люблю детей…",0,280,0,1],["v","И как же не любить рожденных в муках,",0,280,0,0],["v","Взлелеянных. Мне страшно умирать,",0,281,0,0],["v","Но только чернь безумно тратит силы",0,282,0,0],["v","В борьбе с непоправимым злом. Должны,",0,283,0,0],["v","Старик, мы умереть; но пусть не пламя",0,284,0,0],["v","Врагам на посмеянье нас пожрет.",0,285,0,0],["v","Позор нам было 6 тяжелее смерти",0,286,0,0],["v","Предчувствовать. Честь дома нам велит",0,287,0,0],["v","Быть смелыми. Твоя былая слава,",0,288,0,0],["v","Отец, трусливой смерти не допустит.",0,289,0,0],["v","А мой <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>, чья доблесть всем разумным",0,290,0,1],["v","И без свидетелей ясна, — неужто",0,290,0,0],["v","Ты мог бы хоть на миг о нем подумать,",0,291,0,0],["v","Что жизнь детей он купит их позором?",0,292,0,0],["v","Нет, благородный не в одном себе,",0,292,0,0],["v","Он честь свою и в детях охраняет.",0,293,0,0],["v","Что до меня, отец, мне муж — закон.",0,294,0,0],["v","Теперь послушай, о твоих надеждах",0,295,0,0],["v","Что думает <span class=\"ch\" data-ch=\"megara\">Мегара</span>. На возврат",0,295,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> ты надеешься? Да разве",0,296,0,0],["v","Ты слышал, чтобы мертвые вставали?",0,297,0,0],["v","Рассчитывать на милость <span class=\"ch\" data-ch=\"lik\">Лика</span>? Бредни!",0,297,0,0],["v","Вообще, в переговоры с мужиком",0,298,0,0],["v","Входить излишнее. Ведь только умных,",0,299,0,0],["v","Воспитанных покорностью ты тронешь;",0,300,0,1],["v","Одних толковых можно убедить.",0,300,0,0],["v","Изгнанье?.. Ох, я думала об этом,",0,301,0,0],["v","Да разве жизнь изгнанника не мука,",0,302,0,0],["v","Не нищета сплошная? Разве он",0,303,0,0],["v","У приютившего когда увидит",0,303,0,0],["v","Два дня подряд радушное лицо?..",0,304,0,0],["v","Итак, отец, нам остается смерти",0,305,0,0],["v","Смотреть в глаза. Ты с нами осужден",0,306,0,0],["v","И нас теперь не бросишь!.. Заклинаю",0,306,0,0],["v","Тебя твоею благородной кровью…",0,307,0,0],["v","Бороться с повелением богов —",0,308,0,0],["v","Какое жалкое, бесплодное боренье!",0,309,0,0],["v","Какая слепота! Да разве смертный",0,310,0,1],["v","Судьбы решенье изменил хоть раз?",0,310,0,0],["sp","Корифей"],["v","Когда бы силу прежнюю, Мегара,",0,311,0,0],["v","Моим рукам, пускай бы кто посмел",0,312,0,0],["v","Тебя хоть пальцем тронуть, а теперь",0,312,0,0],["v","Что я? Старик бессильный… Ты, <span class=\"ch\" data-ch=\"gerakl\">Гераклов</span>",0,313,0,0],["v","Отец, придумай, как нам поступать.",0,314,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","О нет, Мегара! Нет, не ужас смерти,",0,315,1,0],["v","Не жажду жизни в сердце я носил:",0,315,1,0],["v","Детей, детей берег я для <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>.",0,316,1,0],["v","Но если сохранить их я не в силах, —",0,317,1,0],["v","Эй ты, палач, где нож твой? Режь мне горло!",0,317,1,0],["sd","(Оставляет алтарь. <span class=\"ch\" data-ch=\"megara\">Мегара</span> и дети за ним.)"],["v","Царь! Мы к твоим услугам: если хочешь,",0,318,1,0],["v","Так заколи, не то зарежь, с высокой",0,319,1,0],["v","Скалы нас можешь сбросить. Об одной",0,320,1,1],["v","Молю я милости для матери несчастной",0,320,1,0],["v","И для себя: дозволь нам умереть,",0,321,1,0],["v","Не видя смерти этих бедных крошек.",0,322,1,0],["v","Избавь нас от жестокой пытки. <span class=\"ch\" data-ch=\"lik\">Лик</span>,",0,323,1,0],["v","Мученья смертные их видеть, слышать,",0,324,1,0],["v","Как, плача, нас зовут они на помощь…",0,325,1,0],["v","А остальное делай, как решил.",0,326,1,0],["v","Борьбы и слез от нас ты не увидишь.",0,327,1,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Лик! К этой милости, тебя молю,",0,328,0,0],["v","Прибавь еще одну. Пускай дворец",0,329,0,0],["v","По слову твоему для нас отворят:",0,330,0,1],["v","Мне бы хотелось сыновей <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>",0,330,0,0],["v","Принарядить для смерти: пусть они",0,331,0,0],["v","Отцовское наследство хоть наденут.",0,331,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","На это я согласен и велю",0,332,0,0],["v","Вам отпереть дворец. Веди их в терем.",0,332,0,0],["v","Там, если хочешь, золотом увесь:",0,333,0,0],["v","Нарядов я для вас не пожалею.",0,334,0,0],["v","Когда ж на праздник тело уберешь,",0,334,0,0],["v","Я сам приду убрать его в могилу.",0,335,0,0],["sd","(Уходит со стражей. Перед его уходом по его знаку отворяют дворец.)"],["scene","Явление четвертое","s5",2,5],["v","Те же, без <span class=\"ch\" data-ch=\"lik\">Лика</span> и стражи.",0,335,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Вставайте, дети, и в отцовский дом",0,336,0,0],["v","За горемычной матерью идите!",0,337,0,0],["v","Наш дом теперь он только по названью.",0,337,0,0],["sd","(Уходит во дворец; дети за ней.)"],["scene","Явление пятое","s6",2,6],["v","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span> один.",0,338,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","О Зевс! И это ты к моей жене",0,338,0,0],["v","Всходил на ложе, и отцом <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>",0,339,0,0],["v","Тебя я звал — ты не был другом нам!",0,340,0,1],["v","Неужто ж олимпийца пристыдить",0,341,0,0],["v","Придется человеку! <span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>",0,342,0,0],["v","Не предавал врагам сирот <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>,",0,343,0,0],["v","Как ты их предал, ты, верховный бог,",0,344,0,0],["v","Умеющий так ловко все препоны",0,345,0,0],["v","С пути к чужому ложу удалять.",0,346,0,0],["v","Друзьям в беде помочь не властны боги:",0,347,0,0],["v","Искусства не хватает или сердца.",0,348,0,0],["sd","(Уходит во дворец.)"],["scene","Первый музыкальный антракт","s7",2,7],["str","Строфа I"],["v","По струнам цевницы златой",0,349,2,0],["v","Смычком Аполлон ударяет,<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,350,2,1],["v","И светлые песни сменяет",0,350,2,0],["v","Тоскливый напев гробовой.",0,351,2,0],["v","Я ж гимн погребальный <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>,",0,352,0,0],["v","Сошедшему в область Аида,",0,353,0,0],["v","Из крови ли мужа он вышел,",0,353,0,0],["v","Иль Зевсова кровь в его жилах,",0,354,0,0],["v","Невольно слагаю из песен",0,355,0,0],["v","Торжественно ярких и светлых…",0,356,0,0],["v","Пусть адскою тьмою покрыт он,",0,356,0,0],["v","Но доблесть над мертвым героем",0,357,0,0],["v","Сияет венцом лучезарным.",0,358,0,0],["v","В роще Кронида сначала",0,359,2,0],["v","Страшного льва удавил он,",0,360,2,1],["v","На плечи гордо накинув",0,360,2,0],["v","Шкуру его золотую,",0,361,2,0],["v","Пастью кровавой",0,362,3,0],["v","Светлые кудри",0,362,3,0],["v","Он увенчал.",0,363,3,0],["str","Антистрофа I"],["v","И буйных кентавров стада,",0,364,2,0],["v","Что неслись по лесам и над кручей,",0,364,2,0],["v","Под стрелою <span class=\"ch\" data-ch=\"gerakl\">Геракла</span> летучей",0,365,2,0],["v","К земле прилегли навсегда.",0,366,2,0],["v","А видели это Пенея",0,366,0,0],["v","Вы, пенно-пучинные воды,",0,367,0,0],["v","Фессалии тучные нивы,",0,368,0,0],["v","Которые стали пустыней",0,368,0,0],["v","Под тяжким копытом кентавров,",0,369,0,0],["v","И вы, Пелионские выси,",0,370,0,1],["v","Ущелья Гомола, где сосен,",0,370,0,0],["v","Бывало, себе наломают",0,371,0,0],["v","Кентавры, в поля отправляясь.",0,372,0,0],["v","После с пятнистою шкурой",0,373,2,0],["v","Лань положил он стрелою,",0,374,2,0],["v","Что золотыми рогами",0,375,2,0],["v","Нивы Аркадии рыла;",0,376,2,0],["v","И Артемиде",0,377,3,0],["v","Эту добычу",0,378,3,0],["v","Он посвятил.",0,379,3,0],["str","Строфа II"],["v","Как были ужасны фракийские кони царя Диомеда,",0,380,0,1],["v","Узды они знать не хотели и рыскали в поле,",0,381,0,0],["v","Из челюстей жадных",0,382,2,0],["v","Куски человечьего мяса",0,383,2,0],["v","Торчали меж десен кровавых;",0,384,2,0],["v","Но мощной рукою узду им надел Гераклес.",0,385,0,0],["v","Потом, в колесницу запрягши,",0,386,2,0],["v","Заставил коней переплыть",0,387,2,0],["v","Он Гебра сребристо-пучинные воды.",0,388,0,0],["v","И, подвиг окончив, к царю Еврисфею привел их.",0,389,0,0],["v","А на прибрежье Анавра,",0,390,2,1],["v","Возле горы Пелионской,",0,390,2,0],["v","Меткой стрелой уложил он",0,391,2,0],["v","Зверское чудище — Кикна.",0,391,2,0],["v","Больше проезжих",0,392,3,0],["v","Хищник не будет",0,393,3,0],["v","Подстерегать.",0,393,3,0],["str","Антистрофа II"],["v","На западной грани земельной есть сад, где",0,394,0,0],["v","поют геспериды.",0,395,4,0],["v","Там в зелени древа, склонившего тяжкие ветви,",0,395,0,0],["v","Плоды золотые",0,396,2,0],["v","Сверкают и прячутся в листьях;",0,396,2,0],["v","И, ствол обвивая, багровый",0,397,2,0],["v","То древо бессменно дракон сторожил;",0,398,0,0],["v","Убит он теперь Гераклесом,",0,398,0,0],["v","И с дерева сняты плоды.",0,399,0,0],["v","Герой в морские пучины спускался",0,400,0,1],["v","И веслам людей покорил непокорные волны.",0,400,0,0],["v","В горнем жилище Атланта,",0,401,2,0],["v","Где опустилося небо",0,402,2,0],["v","К лону земному, руками,",0,403,2,0],["v","С нечеловеческой силой,",0,404,2,0],["v","Купол звездистый",0,405,3,0],["v","Вместе с богами",0,406,3,0],["v","Он удержал.",0,407,3,0],["str","Строфа III"],["v","Через бездну Евксина",0,408,1,0],["v","К берегам Меотиды,",0,409,1,0],["v","В многоводные степи,",0,410,1,1],["v","На полки амазонок",0,410,1,0],["v","Много витязей славных",0,411,1,0],["v","За собой он увлек.",0,412,3,0],["v","Там в безумной охоте",0,413,1,0],["v","Он у варварской девы,",0,414,1,0],["v","У Ареевой дщери,",0,415,1,0],["v","Златокованый пояс",0,416,1,0],["v","В поединке отбил:",0,417,3,0],["v","Средь сокровищ микенских",0,418,1,0],["v","Он висит и доселе.",0,419,1,0],["v","Он гидре лернейской",0,420,3,1],["v","Ее неисчетные главы спалил,",0,420,1,0],["v","И ядом змеиным",0,421,3,0],["v","Он меткие стрелы свои напоил,",0,422,1,0],["v","Чтоб ими потом пастуха Гериона убить,",0,423,0,0],["v","Три мертвые тела урода на землю сложить.",0,424,0,0],["str","Антистрофа III"],["v","Много было походов,",0,425,1,0],["v","И побед не исчислить.",0,426,1,0],["v","Но настала путина,",0,427,1,0],["v","Из которой возврата",0,428,1,0],["v","Не бывает для смертных,",0,429,1,0],["v","В царство мрака и слез…",0,430,3,1],["v","А Харон уж на страже:",0,430,1,0],["v","Скоро он и малюток",0,431,1,0],["v","Увезет в ту обитель,",0,432,1,0],["v","Где ни бога, ни правды,",0,433,1,0],["v","Где без выхода дом.",0,433,3,0],["v","На тебя вся надежда,",0,434,1,0],["v","А тебя схоронили.",0,435,1,0],["v","Ты где, моя сила?",0,436,3,0],["v","С тобою, о бранный товарищ, вдвоем",0,436,1,0],["v","Мы верно б отбили",0,437,3,0],["v","Сегодня малюток <span class=\"ch\" data-ch=\"gerakl\">Геракла</span> копьем.",0,438,1,0],["v","Увы! Нашу юность далеко от нас унесло,",0,439,0,0],["v","А с нею и наше счастливое время прошло.",0,440,0,1],["act","Действие второе","a3","II"],["scene","Явление шестое","s8",3,8],["sd","Из дворца выходит <span class=\"ch\" data-ch=\"megara\">Мегара</span>; за ней еле идут испуганные дети в траурных покрывалах. Шествие замыкает <span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>."],["sp","Корифей"],["dir","пока они идут"],["v","Вот, вот они! Смотрите: из чертога",0,441,0,0],["v","Сюда выходят. Видишь, впереди",0,442,0,0],["v","Идет <span class=\"ch\" data-ch=\"megara\">Мегара</span>. Он любил так нежно",0,443,0,0],["v","Ее, покойный. За собой влечет",0,444,0,0],["v","Детей она; в покровах погребальных",0,445,0,0],["v","Малютки еле тянутся, идти",0,446,0,0],["v","Боятся и цепляются руками",0,447,0,0],["v","За складки пеплоса ее. А вот",0,448,0,0],["v","И он, старик отец. Прости, товарищ:",0,449,0,0],["v","Из старых глаз моих катятся слезы…",0,450,0,1],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Ну что же? Где наш жрец, и чья рука",0,451,0,0],["v","Должна поднять свой нож на эту жертву:",0,452,0,0],["v","Она готова; шествие печальное — кого,",0,453,0,0],["v","Кого тут нет: и старики, и дети,",0,454,0,0],["v","И матери… О дети, о родные.",0,455,0,0],["v","Нас разлучат сейчас. Зачем, зачем",0,456,0,0],["v","Я родила вас? Для кого растила?",0,457,0,0],["v","Кому, взрастивши, отдала? Врагам",0,458,0,0],["v","Вас бросила в забаву, в поруганье,",0,459,0,0],["v","На смерть позорную. А вы, мои мечты?",0,460,0,1],["v","Давно ли ваш отец, малютки, царство",0,460,0,0],["v","Свое делил вам, а теперь отца",0,461,0,0],["v","Уж нет. А мы?! Он говорил: \"Ты старший",0,462,0,0],["v","И будешь в Аргосе царем; чертог",0,463,0,0],["v","Тебе на долю будет Еврисфеев",0,463,0,0],["v","И нивы тучные Пеласгии\". Чело<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,464,0,0],["v","Твое он украшал в мечтах трофеем",0,465,0,0],["v","Своей победы первой — львиной пастью.",0,466,0,0],["v","А ты, второй мой сын, тебе в удел",0,466,0,0],["v","Фиванское предназначалось царство;",0,467,0,0],["v","Мои поля ты выпросить сумел",0,468,0,0],["v","С Кадмеей у отца, а в символ власти",0,469,0,0],["v","Он палицу тебе определил,",0,470,0,1],["v","Дедалов дар, предательский гостинец.<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,470,0,0],["v","Ты, наконец, мой младший, получал",0,471,0,0],["v","Эхалию, ту крепость, что стрелою",0,472,0,0],["v","Отец твой добыл. Так мечтал герой<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,473,0,0],["v","Оставить по себе три царства детям,",0,474,0,0],["v","А я невест смышляла сыновьям",0,475,0,0],["v","Из Спарты, из Афин или из здешних",0,476,0,0],["v","Красавиц благородных, чтоб родней",0,477,0,0],["v","Держалось ваше счастье, как канатом",0,478,0,0],["v","Причальным держится у берега триера…",0,479,0,0],["v","Мечты ушли. И брак, который я",0,480,0,1],["v","Для вас теперь справляю, — не веселый:",0,480,0,0],["v","Невесты ваши — Парки, и нельзя<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,481,0,0],["v","Мне ваше ложе брачное украсить:",0,482,0,0],["v","Оно — могила, дети; старый дед",0,482,0,0],["v","Справляет пир, зовя Аида сватом.",0,483,0,0],["v","И веет холодом от брачных похорон…",0,484,0,0],["v","Простимся ж, дети милые! Не знаю,",0,484,0,0],["v","Кого из вас прижать мне к сердцу первым,",0,485,0,0],["v","Кого последним — поцелуй кому",0,486,0,0],["v","Дать первому, кому — последний в жизни?",0,486,0,0],["sd","(Обнимает их, плача.)"],["v","О, если б, как пчела, из ваших губ,",0,487,0,0],["v","Из ваших глаз всю скорбь могла я выпить,",0,488,0,0],["sd","(целует их)"],["v","Чтобы рекою слез теперь оплакать",0,488,0,0],["v","Вас и себя с моею тяжкой мукой!",0,489,0,0],["sd","(С усилием отрываясь от детей.)"],["v","К тебе моя последняя мольба,",0,490,0,1],["v","О мой <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>, о мой супруг желанный!",0,490,0,0],["v","Коль мертвому дано внимать словам",0,491,0,0],["v","Из уст еще живых, то не отвергни",0,491,0,0],["v","Моей мольбы, герой. Старик отец",0,492,0,0],["v","И сыновья твои простились с жизнью,",0,493,0,0],["v","Я свой удел счастливейшей из жен",0,493,0,0],["v","Сейчас закончу под ножом. Не медли ж,",0,494,0,0],["v","Явись, желанный мой, явись хоть тенью,",0,495,0,0],["v","Могильным призраком, виденьем сонным!",0,495,0,0],["v","И трусов тень могильная прогонит,",0,496,0,0],["v","И выронит в испуге нож палач…",0,496,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ну, дочь моя, последние твори",0,497,0,0],["v","Приготовленья к смерти. Я к тебе, Кронид,",0,498,0,0],["v","В последний раз с мольбой подъемлю руки:",0,498,0,0],["v","Не медли, бог верховный! Если ты",0,499,0,0],["v","Спасти детей решил: через минуту",0,500,0,1],["v","Уж будет поздно. Ты молчишь, о Зевс?!",0,500,0,0],["v","Ну что же? Нам в тебе разуверяться",0,501,0,0],["v","Не в первый раз… Как видно, неизбежный",0,502,0,0],["v","Конец настал.",0,502,0,0],["sd","(Хору.)"],["v","Вы, старые друзья,",0,503,4,0],["v","Примите мой завет: наш век короток,",0,504,0,0],["v","И надо так прожить его, чтоб утром",0,504,0,0],["v","О вечере не думать; коли счастлив",0,505,0,0],["v","Теперь ты, так и слава богу! Время",0,506,0,0],["v","Совсем твоих желаний исполнять",0,506,0,0],["v","Не думает. Приходит день и, груз свой",0,507,0,0],["v","Сдав людям, дальше он идет… Не я ли",0,508,0,0],["v","Был горд и славен, счастлив был, и что же?",0,508,0,0],["v","День привела судьба, и это счастье",0,509,0,0],["v","Он смел, как ветер — легкое перо.",0,510,0,1],["v","Не знаю уж, случается ль, чтоб счастлив",0,510,0,0],["v","Всю жизнь был человек, чтобы ему",0,511,0,0],["v","Бессменным спутником служила слава. Старцы,",0,512,0,0],["v","Вы были верными друзьями мне. Простите ж",0,512,0,0],["v","Перед разлукой вечной старику!",0,513,0,0],["sd","(Кланяется им.)"],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["dir","всматриваясь в даль"],["v","Но что со мной? Не может быть… я брежу…",0,514,0,0],["v","Смотри, отец! Ведь это он, мой муж!..",0,514,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","смотря в ту же сторону, раздельно и с усилием"],["v","Не знаю, дочь моя… боюсь поверить.",0,515,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Сомненья прочь и суеверный страх!",0,516,0,0],["v","Ведь призраки ночные перед солнцем",0,516,0,0],["v","Бегут, старик. Нет, это он — твой сын,",0,517,0,0],["v","Которого так долго мы считали",0,518,0,0],["v","Умершим.",0,518,0,0],["sd","(Детям.)"],["v","Дети милые, к отцу",0,519,3,0],["v","Бегите, за одежду ухватитесь,",0,520,0,1],["v","Чтоб не ушел от нас опять. Он — бог,",0,521,0,0],["v","Он ваш теперь Зевес-спаситель, дети.",0,522,0,0],["scene","Явление седьмое","s9",3,9],["sd","Пока <span class=\"ch\" data-ch=\"megara\">Мегара</span> говорит свои последние слова, со стороны, противоположной той, откуда появлялся хор и <span class=\"ch\" data-ch=\"lik\">Лик</span>, показывается <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>, в царской одежде, без львиной шкуры, с луком и колчаном. Первые слова он говорит на ходу."],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Благословенны вы, мой отчий кров",0,523,0,0],["v","И ворота отцовские! как сладко",0,524,0,0],["v","Увидеть вас и чувствовать, что жив!",0,525,0,0],["v","Ба… это что? За воротами дети,",0,526,0,0],["v","На них покровы мертвых; старики",0,527,0,0],["v","Какие-то вокруг жены толпятся…",0,528,0,0],["v","Отец в слезах. Что ж это значит? Разве",0,529,0,0],["v","Беда какая на моем дворе?",0,530,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","подходя к сыну"],["v","О свет очей моих, о сын мой милый,",0,530,0,0],["v","Спасенный, ты спасенье нам несешь.",0,531,0,0],["v","Как вовремя!.. Одной минутой позже…",0,532,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Кончай, отец! Беда стряслась над вами?",0,533,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["dir","перебивая <span class=\"ch\" data-ch=\"amfitrion\">Амфитриона</span>"],["v","Да, нас вели на казнь. Прости, старик,",0,534,0,0],["v","Что женщина перехватила слово",0,535,0,0],["v","Из уст твоих. Я дольше не могла",0,535,0,0],["v","Таить волнение. Подумать, что малюток",0,536,0,0],["v","В своих объятьях смерть уже держала…",0,537,0,0],["sd","(Закрывает лицо руками.)"],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Какое страшное начало, Аполлон!",0,538,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Убит отец мой, и убиты братья.",0,539,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Что слышу? Чей же меч их уложил?",0,540,0,1],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","<span class=\"ch\" data-ch=\"lik\">Лик</span> их убийца, новый царь фиванский.",0,541,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","В бою или в усобице убил?",0,542,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","О нет, — мятеж доставил трон тирану.",0,543,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но ты и мой отец, при чем же вы?",0,544,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","<span class=\"ch\" data-ch=\"lik\">Лик</span> осудил на смерть твое семейство.",0,545,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Что ж? Он боялся маленьких детей?",0,546,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Их мести он боялся за Креонта.",0,547,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","взглядывая на детей"],["v","Но их наряд! Так в гроб кладут людей.",0,548,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Да я и наряжала их для гроба.",0,549,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","О, боги! Смерть глядела на детей.",0,550,0,1],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Тебя считали мертвым. Мы ж так слабы.",0,551,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Про смерть мою откуда знали вы?",0,552,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","От Еврисфея были здесь герольды.",0,553,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но кто же из дворца вас мог прогнать?",0,554,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Нас силой выгнали… Отца с постели…",0,555,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Согнать с постели старца?! Что за стыд!",0,556,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Стыд? Разве <span class=\"ch\" data-ch=\"lik\">Лик</span> знаком с богиней этой?",0,557,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но я друзей имел здесь, что ж друзья?",0,558,0,0],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Друзей искать задумал у несчастных!",0,559,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","И лавры уж Геракловы не в счет?",0,560,0,1],["sp","<span class=\"ch\" data-ch=\"megara\">Мегара</span>"],["v","Опять скажу: с бедой не ладит дружба.",0,560,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","к детям"],["v","А, ты все здесь еще, убор гробов?..",0,561,0,0],["v","Прочь с детской головы!",0,562,0,0],["sd","(Срывает покрывала с детей.)"],["v","Смотрите смело",0,563,4,0],["v","На божий свет, малютки, и забудьте",0,564,0,0],["v","Про темную могилу. Разве кто",0,565,0,0],["v","Обидит Гераклидов? Пришлеца",0,565,0,0],["v","И узурпатора на землю с трона",0,566,0,0],["v","Я сброшу, голову венчанную срублю",0,567,0,0],["v","И кину в снедь собакам, а фиванцев,",0,568,0,0],["v","Толпу неблагодарную, вот эта",0,569,0,0],["sd","(поднимает палицу)"],["v","Моя подруга всех угомонит",0,570,0,1],["v","Иль стрелы легкие пронижут; в волны",0,570,0,0],["v","Исмена светлого кровавые тела",0,571,0,0],["v","Я побросаю, и Диркеи лоно",0,572,0,0],["v","Окрасится пурпуровой струей.",0,573,0,0],["v","Ты, длань моя, привыкшая к работе,",0,573,0,0],["v","Моей семье сегодня послужи!",0,574,0,0],["v","Победы, лавры! Что за прок в победах,",0,575,0,0],["v","Когда готовы были умереть",0,576,0,0],["v","За победителя-<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> крошки дети?",0,576,0,0],["v","И как смешно бы было в самом деле,",0,577,0,0],["v","Когда бы после всех трудов герой,",0,578,0,0],["v","И льва немейского, и красного дракона<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,579,0,0],["v","Для Еврисфея одолевший, отомстить",0,580,0,1],["v","Не захотел врагам своей семьи,",0,580,0,0],["v","Победы не искал бы, без которой",0,581,0,0],["v","Все прочие — ничтожная забава!",0,582,0,0],["sp","Корифей"],["v","Достойно мужа справедливого идти",0,583,0,0],["v","Своей охотой на спасенье старца",0,584,0,0],["v","Отца, супруги милой и детей.",0,585,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Опорой для друзей, врагам грозою",0,585,0,0],["v","Ты был всегда. Но здесь не горячись!",0,586,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты видишь в замыслах моих горячность?",0,587,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Знай: много нищих, что хотят казаться",0,588,0,0],["v","Богатыми, захватчика поддержат:",0,589,0,0],["v","Мятеж подняли и сгубили город",0,590,0,1],["v","Затем они, чтобы добро чужое",0,590,0,0],["v","Разграбить, промотав сперва свое",0,591,0,0],["v","На праздные попойки и пирушки.",0,592,0,0],["v","Довольно и того, что твой приход<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,592,0,0],["v","Врагами был замечен и собраться",0,593,0,0],["v","Они имели время. Не давай",0,594,0,0],["v","Теперь врасплох застать себя тирану.",0,594,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","И горя мало: пусть бы хоть и все",0,595,0,0],["v","Кадмейцы видели меня, да по дороге",0,596,0,0],["v","Смутил меня зловещий птичий знак;<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,596,0,0],["v","Я ожидал найти несчастье в доме",0,597,0,0],["v","И к вам, отец, вошел я незаметно.",0,598,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Вот и отлично. А теперь пойди",0,598,0,0],["v","И очагу привет скажи, пусть стены",0,599,0,0],["v","Отцовские лицо твое увидят.",0,600,0,1],["v","<span class=\"ch\" data-ch=\"lik\">Лик</span> все равно и сам сюда придет",0,600,0,0],["v","За нами, чтоб на казнь вести. Тогда ты",0,601,0,0],["v","Здесь, во дворце, с ним справишься спокойно;",0,602,0,0],["v","А город на ноги не поднимай,",0,603,0,0],["v","Пока с тираном счетов не покончишь.",0,604,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Благодарю, отец, и твой совет",0,605,0,0],["v","Исполню. В грустном царстве Персефоны",0,606,0,0],["v","И Гадеса, где вечный мрак лежит,",0,607,0,0],["v","Скитался долго я, и поклониться",0,608,0,0],["v","Родным богам уж мне давно пора.",0,609,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ты в преисподнюю спускался, так ли?",0,610,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Оттуда только что я Кербера привел.",0,611,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Осилил или в дар приял от Коры?",0,612,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Осилил, таинства сподобившись узреть.",0,613,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","И что же? Чудище уже в Микенах?",0,614,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Нет, в роще Коры я оставил пса.",0,615,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Так царь еще об этом и не знает?",0,616,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Всех вас спешил я раньше повидать.",0,617,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Но ты так долго пробыл в царстве Коры?",0,618,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Освобождал <span class=\"ch\" data-ch=\"tesey\">Тесея</span> я, отец.",0,619,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","<span class=\"ch\" data-ch=\"tesey\">Тесея</span>? Где ж он? Верно, уж в отчизне?",0,620,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Как только свет опять он увидал,",0,620,0,0],["v","Сейчас же заспешил в свои Афины.",0,621,0,0],["v","Ну, дети, полно жаться! Мы пойдем",0,622,0,0],["v","Теперь домой, и будет веселее,",0,622,0,0],["v","Конечно, возвращенье вам, чем выход.",0,623,0,0],["v","Но будьте же мужчинами! Опять",0,624,0,0],["v","Вы плачете. А ты, моя <span class=\"ch\" data-ch=\"megara\">Мегара</span>,",0,624,0,0],["v","Ты вся дрожишь! Пустите же меня!",0,625,0,0],["v","Зачем вы, мальчики, в меня вцепились?",0,626,0,0],["v","Не птица ж в самом деле ваш отец,",0,626,0,0],["v","Что вдруг возьмет да улетит; и разве",0,627,0,0],["v","Я убегу от вас, моих любимых?",0,628,0,0],["v","О господи!",0,628,0,0],["v","Ведь не пускают! Как клещи впились",0,629,0,0],["v","Руками в перекидку! Что тут делать?",0,630,1,1],["v","Что? Очень напугались? Ну, вперед!",0,630,0,0],["v","Я заберу вас всех троих и буду",0,631,0,0],["v","Большой корабль, а вы за мной, как барки,",0,632,0,0],["v","Потянетесь.",0,633,0,0],["sd","(Поднимает их и идет в ворота. <span class=\"ch\" data-ch=\"megara\">Мегара</span> и отец за ними.)"],["v","Да, люди всюду те же:",0,634,4,0],["v","Те побогаче, эти победнее,",0,635,0,0],["v","А дети всякому свои милы.",0,636,0,0],["scene","Второй музыкальный антракт","s10",3,10],["sp","Хор"],["str","Строфа I"],["v","Хорошо человеку, как молод!",0,637,0,0],["v","Тяжела ему старость.",0,638,0,0],["v","Словно Этны тяжелые скалы",0,639,0,0],["v","Долу голову старую клонят,",0,640,0,1],["v","И не видит он божьего света.",0,641,0,0],["v","Дай нам на выбор:",0,642,2,0],["v","Трон ассирийский,",0,643,2,0],["v","Золота горы,",0,644,2,0],["v","Старость с костей, —",0,645,2,0],["v","Молодость спросим:",0,646,2,0],["v","В золоте молод,",0,647,2,0],["v","В рубище молод,",0,648,2,0],["v","Да не завистлив.",0,649,2,0],["v","Завейте вы, буйные вихри,",0,650,0,1],["v","Несите вы горькую старость",0,651,0,0],["v","Далеко, на синее море!",0,652,0,0],["v","Пусть будет зарок ей положен",0,653,0,0],["v","В жилище входить к человеку,",0,654,0,0],["v","Пусть вечно, земли не касаясь,",0,655,0,0],["v","Пушинкой кружится в эфире.",0,656,0,0],["str","Антистрофа I"],["v","Если б боги людей различали",0,657,2,0],["v","В провидении мудром,",0,658,2,0],["v","Мог бы добрый две юности видеть,",0,659,0,0],["v","После смерти весной насладиться.",0,660,0,1],["v","А дурные, в ком нет благородства,",0,660,0,0],["v","Так бы и были:",0,661,2,0],["v","Отжили век свой,",0,662,2,0],["v","Да и в могилу.",0,663,2,0],["v","Как мореход",0,663,2,0],["v","Через туманы",0,664,2,0],["v","Звезды считает,",0,665,2,0],["v","Правду на смертных",0,666,2,0],["v","Мы бы читали.",0,666,2,0],["v","Могли бы тогда различать мы,",0,667,0,0],["v","Кто истинно был благороден:",0,668,0,0],["v","Печатью бы злые клеймились…",0,669,0,0],["v","Нет божьего знака на людях;",0,670,0,1],["v","Кружит колесо нас: то склонит,",0,670,0,0],["v","То в гору поднимет, и только",0,671,0,0],["v","Богатый вверху остается.",0,672,0,0],["str","Строфа II"],["v","Нет, не покину, Музы, алтарь ваш;",0,673,0,0],["v","Вы же, Хариты, старца любите!",0,674,0,0],["v","Истинной жизни нет без искусства…",0,675,0,0],["v","Зеленью плюща белые кудри",0,676,0,0],["v","Я увенчаю. Лебедь весь белый,",0,677,0,0],["v","Но не мешайте петь ему, люди!",0,678,0,0],["v","Пусть он былому песню слагает,",0,679,0,0],["v","Пусть он победы славит <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>.",0,680,0,1],["v","Когда ж польется в чаши",0,681,2,0],["v","Дар Вакха благодатный,",0,682,2,0],["v","Иль понесутся звуки",0,683,2,0],["v","Цевницы семиструнной,",0,684,2,0],["v","Иль заиграет флейта, —",0,685,2,0],["v","Оставив хороводы,",0,686,2,0],["v","Побудь со мною, Муза!",0,687,2,0],["str","Антистрофа II"],["v","Гимном победным сына Латоны",0,688,0,0],["v","Славят, кружася, Делоса девы,",0,689,0,0],["v","Праздничной пляской бога встречают;",0,690,0,1],["v","Я ж, одряхлевший, возле чертога",0,690,0,0],["v","Голосом слабым славлю <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>.",0,691,0,0],["v","Лебедь весь белый, но не мешайте",0,692,0,0],["v","Петь ему, люди: песня годится,",0,693,0,0],["v","Если он славит то, что прекрасно.",0,694,0,0],["v","В герое кровь Зевеса,",0,695,2,0],["v","Но выше крови знатность",0,695,2,0],["v","Дела ему стяжали:",0,696,2,0],["v","Без бурь на белом свете",0,697,2,0],["v","Прожить теперь мы можем,",0,698,2,0],["v","И под могучей дланью",0,699,2,0],["v","Чудовища смирились.",0,700,2,1],["act","Действие третье","a4","III"],["scene","Явление восьмое","s11",4,11],["sd","<span class=\"ch\" data-ch=\"lik\">Лик</span> (с прежней стороны), за ним <span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span> (из дворца)."],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Ну, наконец-то ты, Амфитрион,",0,700,0,0],["v","Пожаловал! Не торопились, видно,",0,701,0,0],["v","Для смерти наряжать вы Гераклидов",0,702,0,0],["v","Да погребальные покровы выбрать…",0,703,0,0],["v","Ну, поскорей зови сюда <span class=\"ch\" data-ch=\"megara\">Мегару</span>,",0,704,0,0],["v","Пускай детей ведет: решили вы",0,705,0,0],["v","Без споров подчиниться мне, не так ли?",0,705,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Лик! Я нуждой придавлен, и меня",0,706,0,0],["v","Легко преследовать, над беззащитным",0,707,0,0],["v","Ругаться; поскромней бы надо быть",0,708,0,0],["v","Тебе, хоть и сильнее нас теперь ты.",0,709,0,0],["v","Царь нашей жизни требует? Ну что ж,",0,710,0,1],["v","Конечно, мы должны повиноваться…",0,711,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Да где ж <span class=\"ch\" data-ch=\"megara\">Мегара</span>? Где ее приплод?",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Дверь заперта. Насколько можно слышать…",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Что слышать?.. Коли начал, говори!",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","У очага с детьми <span class=\"ch\" data-ch=\"megara\">Мегара</span> плачет.",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Но слезы бесполезны ей, старик!",0,716,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Взывает к мужу там она, и тщетно.",0,717,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> нет, откуда ж он придет?",0,718,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","А если боги воскресят героя?",0,719,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Оставь, старик. Сноху сюда веди!",0,720,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","раздельно"],["v","Ты мне велишь вести на казнь <span class=\"ch\" data-ch=\"megara\">Мегару</span>?",0,720,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["v","Все эти тонкости, почтенный, не для нас.",0,721,0,0],["v","Я мать с детьми сейчас и сам доставлю.",0,722,0,0],["v","Эй вы, приспешники! за мною во дворец!",0,723,0,0],["v","Пора нам с плеч свалить обузу эту.",0,724,0,0],["sd","(Уходит со стражей.)"],["scene","Явление девятое","s12",4,12],["v","Те же без <span class=\"ch\" data-ch=\"lik\">Лика</span>.",0,725,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ушел… Небось обратно не придет.",0,725,0,0],["v","Туда тебе, злодею, и дорога!",0,726,0,0],["v","Там полностью получишь свой расчет…",0,727,0,0],["v","Друзья мои! Подлейший из тиранов",0,728,0,0],["v","В железную теперь попался сеть;",0,729,0,0],["v","Остривший меч сам от меча погибнет.",0,730,0,1],["v","Пойти, полюбоваться, как его",0,731,0,0],["v","Уложат. Сладко нам смотреть на кару",0,732,0,0],["v","Злодея и увидеть смерть врага.",0,733,0,0],["sp","Хор"],["str","Строфа I"],["v","Довольно бед!",0,734,2,0],["v","Из адской тьмы холодной",0,735,2,0],["v","Пришел наш царь природный",0,736,2,0],["v","На вольный божий свет.",0,737,2,0],["v","И новая жизнь покатилась веселой волной.",0,738,0,0],["v","О, будьте вы, правые боги, со мной!",0,739,0,0],["sp","Корифей"],["v","Недолго <span class=\"ch\" data-ch=\"lik\">Лик</span> поцарствовал, и жизнью",0,740,0,1],["v","Заплатит он за поруганье добрых.",0,741,0,0],["sp","Хор"],["v","Слез не могу сдержать,",0,742,0,0],["v","Радости светлых слез.",0,743,0,0],["v","Смел ли я ждать тебя?",0,744,0,0],["v","Ты ли со мной,",0,745,0,0],["v","Царь мой, природный царь?",0,746,0,0],["sp","Корифей"],["v","Подумаем о том, что там, в чертоге:",0,747,0,0],["v","Свершается ль души моей желанье?",0,748,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["dir","за сценой"],["v","Ой… ой…",0,749,0,0],["sp","Хор"],["v","Постой, старик,",0,750,0,1],["str","Антистрофа I"],["v","Склони-ка долу ухо:<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,747,0,0],["v","Там кто-то стонет глухо,",0,744,0,0],["v","А что? Ведь это <span class=\"ch\" data-ch=\"lik\">Лик</span>!",0,741,0,0],["v","Стоны продолжаются. Слышно падение тела.",0,738,0,0],["v","Отрадно нам слушать, как жалобно стонет тиран,",0,735,0,0],["v","Как валится наземь, терзаясь от ран.",0,732,0,0],["sp","<span class=\"ch\" data-ch=\"lik\">Лик</span>"],["dir","за сценой"],["v","Все, все ко мне, я в западне, убит я!",0,729,0,0],["v","Ой, лихо мне! Ой, смерть!",0,725,0,0],["sp","Корифей"],["v","Убит убийца. По делам награда:",0,722,0,0],["v","Не сетуй же, — лишь равным бог воздал.",0,719,0,0],["sp","Хор"],["v","Жалкий безумец ты,",0,716,0,0],["v","Если на миг дерзнешь",0,713,0,0],["v","В мысли кощунственной",0,710,0,0],["v","Слабым признать",0,707,0,0],["v","Бога всесильного.",0,704,0,0],["sp","Корифей"],["v","Друзья! Умолкли стоны, и тиран",0,700,0,1],["v","Убит, восславим же свободу!",0,701,0,0],["scene","Третий музыкальный антракт","s13",4,13],["sp","Хор"],["str","Строфа II"],["v","Завивайтесь кольцом, хороводы,",0,702,0,0],["v","Пируйте, священные Фивы!",0,703,0,0],["v","С солнца счастья сбежали тени,",0,704,0,0],["v","И вернулись светлые песни.",0,705,0,0],["v","Больше нет над нами тирана.",0,706,0,0],["v","Адский мрак нам вернул героя:",0,770,0,1],["v","То, что было безумною сказкой,",0,771,0,0],["v","Непреложной истиной стало.",0,772,0,0],["str","Антистрофа II"],["v","Беспредельна власть олимпийцев",0,773,0,0],["v","Над добрым и злым человеком.",0,774,0,0],["v","Часто смертного манит злато,",0,775,0,0],["v","К высям славы мечты уносят.",0,776,0,0],["v","Но лишь палицу время подымет,",0,777,0,0],["v","Задрожит забывший про бога;",0,778,0,0],["v","И летит с высоты колесница,",0,779,0,0],["v","Вся обрызгана грешною кровью.",0,780,0,1],["str","Строфа III"],["v","Венком уберися, Исмен мой!",0,781,2,0],["v","Вы, улицы Фив, развернитеся шире для пляски сегодня;",0,782,0,0],["v","Приди к нам на праздник и ты,",0,783,2,0],["v","Диркея, из темной пучины,",0,784,2,0],["v","И ты приводи своих дочек, Асоп!<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,785,2,0],["v","Пускай эти нимфы",0,786,2,0],["v","Нам хором согласным споют",0,787,2,0],["v","Про славные битвы <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>!",0,788,2,0],["v","А вы, геликонские рощи,",0,790,2,1],["v","Где Музы живут,",0,791,2,0],["v","Откройтесь для звуков победных,",0,792,2,0],["v","Звучите фиванскою славой,",0,793,2,0],["v","Исконною славой ее земнородных князей!",0,794,1,0],["v","Те спарты в тяжелых доспехах",0,795,2,0],["v","Священные Фивы потомкам",0,796,2,0],["v","На славу свою сберегли.",0,797,2,0],["str","Антистрофа III"],["v","Рожденье <span class=\"ch\" data-ch=\"gerakl\">Геракла</span> чудесно:",0,798,2,0],["v","К Персеевой внуке на ложе бессмертный и смертный входили;<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,800,0,1],["v","Обоих прияла она.",0,800,2,0],["v","Я верил всегда, что в герое",0,801,2,0],["v","Течет небожителя славная кровь.",0,802,2,0],["v","Но кто же из смертных",0,803,2,0],["v","Дерзнет сомневаться теперь,",0,804,2,0],["v","Когда олимпиец, так живо",0,805,2,0],["v","Из адского мрака исторгнув,",0,806,2,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> явил,",0,807,2,0],["v","Что точно он зачат был богом?",0,808,2,0],["v","Ты царь мой, ты истинный царь мой.",0,809,2,0],["v","И <span class=\"ch\" data-ch=\"lik\">Лик</span> этот жалкий ничтожен в сравненье с тобой:",0,810,0,1],["v","Недаром, мечом пораженный,",0,811,2,0],["v","На опыте горьком познал он,",0,812,2,0],["v","Что в небе есть правда и бог.",0,813,2,0],["act","Действие четвертое","a5","IV"],["scene","Явление десятое","s14",5,14],["sd","Набегает мрак. Глухие раскаты грома. В воздухе, над домом <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>, показывается Ирида, крылатая молодая богиня, в шафранном пеплосе, и Лисса, страшное, худое созданье, в черном, со змеями в черных волосах и с отвратительным лицом."],["sp","Корифей"],["v","Га! Что это?",0,814,0,0],["v","Иль буря новая грозит нам, старцы?",0,815,0,0],["v","Смотрите, призраки над домом поднялись…",0,816,0,0],["sp","Один из хора"],["v","Беги! Беги!",0,817,0,0],["v","Ох, уносите, ноги старые, беги!",0,818,0,0],["v","Второй из хора",0,819,0,0],["v","Царь Аполлон!",0,820,0,1],["v","Владыка, сохрани от наважденья!",0,820,0,0],["sp","Ирида"],["dir","жестом успокаивая стариков"],["v","Смелее, люди! Зла мы не хотим",0,821,0,0],["v","Ни вам, ни городу. Со мною Лисса,",0,822,0,0],["v","Рожденная от Ночи, я ж — Ирида,",0,823,0,0],["v","Богов посланница. А ополчились мы",0,824,0,0],["v","На смертного, который позволяет",0,825,0,0],["v","Себя звать сыном Зевса и Алкмены.",0,825,0,0],["v","Пока он не свершил своих трудов",0,826,0,0],["v","Тяжелых, все судьба его хранила;",0,827,0,0],["v","О нем заботился отец Зевес, и нам,",0,828,0,0],["v","Мне с Герой, не давал его в обиду.",0,829,0,0],["v","Но порученья Еврисфея он",0,830,0,1],["v","Окончил, и теперь охрана снята.",0,830,0,0],["v","Угодно Гере, чтоб обиду, ей",0,831,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Гераклом</span> нанесенную, он кровью",0,831,0,0],["v","Своих детей сегодня заплатил.",0,832,0,0],["v","Угодно Гере так, и мне угодно.",0,833,0,0],["sd","(Лиссе.)"],["v","Ты ж, брака не познавшая, ты, дщерь",0,833,0,0],["v","Глубокой ночи, собери всю злобу",0,834,0,0],["v","В груди безжалостной! Теперь на мужа,",0,835,0,0],["v","Для Геры ненавистного, должна ты",0,835,0,0],["v","Наслать безумье яркое. Пусть ноги",0,836,0,0],["v","Танцуют танец сумасшедший, мозг",0,836,0,0],["v","Его горит от бешеных желаний",0,837,0,0],["v","Детоубийцы: разнуздай его,",0,838,0,0],["v","Заставь своей рукой в пасть жадной смерти",0,838,0,0],["v","Толкать детей цветущих. Пусть познает",0,839,0,0],["v","Он ненависть царицы — и мою",0,840,0,1],["v","Оценит! Что бы стало с вами, боги,",0,840,0,0],["v","Когда б для кары вышних человек",0,841,0,0],["v","В величье оставался недоступным?",0,842,0,0],["sp","Лисса"],["v","От крови знатной я, и из утробы<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,842,0,0],["v","Я вышла благородной. Мой отец",0,843,0,0],["v","Был Небосвод, а мать зовется Ночью.",0,844,0,0],["v","Но, как богине, мне досталась доля,",0,845,0,0],["v","Противная бессмертным. И самой",0,845,0,0],["v","Мне горько посещать обитель дружбы.",0,846,0,0],["v","Ирида, прежде чем вас допустить",0,847,0,0],["v","До роковой ошибки, я должна вам",0,847,0,0],["v","Сказать: одумайтесь! Тот человек,",0,848,0,0],["v","Чей дом ты указала мне, недаром",0,849,0,0],["v","Известен на земле и славен в небе:",0,850,0,1],["v","Он сушу непролазную, он море",0,850,0,0],["v","Суровое смирил и отдал людям,",0,851,0,0],["v","Восстановил служение богам,",0,852,0,0],["v","Разбойников преступными руками",0,852,0,0],["v","Смятенное, — все он один. Так Гере,",0,853,0,0],["v","Да и тебе, Ирида, мой совет —",0,854,0,0],["v","Не трогайте <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>: это дурно.",0,855,0,0],["sp","Ирида"],["v","Геры план, мое решенье ты не призвана судить.",0,855,0,0],["sp","Лисса"],["v","Но стопы твои на правый путь хочу я обратить.",0,856,0,0],["sd","Ирида."],["v","Да на что ж теперь нам с Герой доброта твоя, скажи?",0,857,0,0],["sp","Лисса"],["v","Солнце вышнее, ты слышишь? Расскажи же, солнце, людям",0,857,0,0],["v","Что в <span class=\"ch\" data-ch=\"gerakl\">Гераклов</span> дом вступаю не своей я вольной волей:",0,858,0,0],["v","Так царица захотела, и Ирида приказала,",0,859,0,0],["v","И бегу я, как собака, что за дичью посылают.",0,860,0,1],["v","Молния и гром.",0,860,0,0],["v","А теперь — за дело, Лисса! И клянуся я, что море",0,861,0,0],["v","Так не выло в непогоду, волны тяжкие сдвигая,",0,861,0,0],["v","Так земля не содрогалась и, по небу пролетая,",0,862,0,0],["v","Столько ужаса и смерти стрелы молний не носили,",0,863,0,0],["v","Сколько ужаса, и воя, и безумных содроганий",0,863,0,0],["v","Принесу я в грудь <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>. Я чертог его разрушу,",0,864,0,0],["v","Размечу колонны дома. Но сперва детей убьет он;",0,865,0,0],["v","Да, своей рукой малюток умертвит он без сознанья…",0,865,0,0],["v","Долго, долго после будет сон его кровавый длиться.",0,866,0,0],["v","…Видишь, видишь, — началося. Голова от гнева ходит;",0,866,0,0],["v","Сам ни звука, точно скован. Только белые шары",0,867,0,0],["v","Все по впадинам катает, да высоко и неровно",0,868,0,0],["v","Ходит грудь его скачками. Точно бык, готов он прянуть…",0,868,0,0],["v","Вот из сдавленного горла воздух вырвался со свистом.",0,869,0,0],["v","Грозным ревом смерть зовет он. Скоро, скоро, — погоди, —",0,870,0,1],["v","Дикий танец затанцуешь, бледный страх флейтистом будет…",0,870,0,0],["v","На Олимп лети к бессмертным, благородная Ирида!",0,871,0,0],["v","Мне же надо невидимкой в этот царский дом спуститься.",0,872,0,0],["v","Обе исчезают.",0,873,0,0],["sp","Хор"],["v","Увы мне! Увы мне! Увы мне!",0,874,2,0],["v","Ты плачь и стенай,",0,875,2,0],["v","Эллада, Эллада!",0,875,3,0],["v","Срезан серпом твой цвет;",0,876,2,0],["v","Вот он, твой славный вождь,",0,877,2,0],["v","Адскому визгу внимая,",0,878,2,0],["v","Носится в пляске безумной.",0,879,2,0],["v","Вот и она",0,880,3,1],["v","На колеснице,",0,880,3,0],["v","Царица слез.",0,881,3,0],["v","Бешено мчат ее кони.",0,881,2,0],["v","Сама же дочь Ночи, Горгона,",0,882,2,0],["v","Подъятым стрекалом",0,882,3,0],["v","Их колет и дразнит;",0,883,3,0],["v","А змеи и вьются и свищут",0,883,2,0],["v","Средь угольно-черных волос.",0,884,2,0],["v","Трудно ли богу счастье разрушить?",0,885,0,0],["v","Долго ль малюткам детоубийце",0,885,0,0],["v","Души отдать?",0,886,3,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","за сценой"],["v","О, горе! О, горе мне!",0,886,0,0],["sp","Хор"],["v","Горе, о Зевс!",0,887,0,0],["v","Сын твой лишится сейчас сыновей.",0,887,0,0],["v","Он грянется наземь, осилен",0,888,0,0],["v","Духами бешеной злобы и кары,",0,888,0,0],["v","Хищным отродьем подземного царства.",0,889,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","за сценой"],["v","О, горе дому нашему!",0,890,0,1],["sp","Хор"],["v","Вот в хороводе кружиться пошел;",0,890,0,0],["v","Только тимпанов не слышно,",0,891,0,0],["v","Тирсов не видно, что Бромию милы.",0,892,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","за сценой"],["v","О, сень моя!",0,892,0,0],["sp","Хор"],["v","Вот он готовится жертву заклать…",0,893,0,0],["v","Но не козленка для жертвы<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,894,0,0],["v","Жаждет, безумный, не Вакховой влаги.",0,895,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","за сценой"],["v","Бегите, дети! Шибче, шибче, дети!",0,895,0,0],["sp","Хор"],["v","Крики-то, крики-то!",0,896,0,0],["v","Безумный ловец,",0,897,2,0],["v","По дому он ищет детей…",0,897,2,0],["v","О, Лисса недаром пришла пировать:",0,898,0,0],["v","Без жертвы не будет.",0,899,2,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","за сценой"],["v","О, злые бедствия!",0,900,0,1],["sp","Хор"],["v","Горе тебе,",0,900,2,0],["v","Старый отец!",0,901,2,0],["v","С матерью горькой,",0,901,0,0],["v","В муках на муку родившей,",0,902,0,0],["v","С матерью плачу я.",0,903,2,0],["scene","Явление одиннадцатое","s15",5,15],["sd","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span> на минуту показывается из дворца, где с треском рушатся колонны и падают стены."],["sp","Один из хора"],["v","В чертогах буря, валятся колонны.",0,903,0,0],["sd","Несколько подземных ударов, и затем продолжительный гул. Огромный призрак Паллады с копьем и в шлеме входит во дворец."],["sp","Хор"],["v","О, боги! Но ты,",0,904,2,0],["v","Чего же ты ищешь в чертогах,",0,905,0,0],["v","Дочь Неба, Паллада?",0,905,2,0],["v","Ты тяжко ступаешь…",0,906,2,0],["v","Так некогда в битву",0,906,2,0],["v","С гигантами шла ты,",0,907,2,0],["v","И так же дрожала земля",0,908,0,0],["v","До недр сокровенных.",0,908,2,0],["scene","Явление двенадцатое","s16",5,16],["v","Вестник выбегает из дворца.",0,909,0,0],["sp","Вестник"],["v","Вы, старцы белые…",0,910,0,1],["sp","Хор"],["v","Ты, ты зовешь меня?",1,910,0,0],["sp","Вестник"],["v","О, что за ужас там!",0,910,0,0],["sp","Хор"],["v","Надо ль угадывать?",1,910,0,0],["sp","Вестник"],["v","Убиты мальчики…",0,911,0,0],["sp","Хор"],["v","Горе нам, горе нам!",1,911,0,0],["sp","Вестник"],["v","Да, плачьте: это ст<em>о</em>ит слез.",0,912,0,0],["sp","Хор"],["v","Как страшен",1,912,0,0],["v","Детоубийца был, я думаю!",0,913,0,0],["sp","Вестник"],["v","Как страшен был, не спрашивай, старик:",0,914,0,0],["v","У пережившего нет слов для описанья.",0,915,0,0],["sp","Хор"],["dir","настойчиво"],["v","Коль видел ты гнусный тот грех,",0,916,0,0],["v","Отца и детей поразивший,",0,917,0,0],["v","Нам все без утайки теперь расскажи:",0,918,0,0],["v","Как, насланный богом, вошел",0,919,0,0],["v","Злой демон в царевы чертоги,",0,920,0,1],["v","Как детские жизни сначала,",0,920,0,0],["v","А после и стены разрушил.",0,921,0,0],["sp","Вестник"],["v","У алтаря Зевесова <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>",0,921,0,0],["v","Готовился свой двор очистить жертвой",0,922,0,0],["v","От крови <span class=\"ch\" data-ch=\"lik\">Лика</span> пролитой, тирана,",0,923,0,0],["v","Которого он только что убил.",0,923,0,0],["v","Его венцом прекрасным окружали",0,924,0,0],["v","И сыновья, и мать их, и старик",0,925,0,0],["v","Отец. А мы, рабы их, тесно",0,925,0,0],["v","Вкруг алтаря толпились, и в ходу",0,926,0,0],["v","Уже была корзина, уж молчанье<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,926,0,0],["v","Хранили мы благоговейно. Взяв",0,927,0,0],["v","Горящий уголь, господин сбирался",0,928,0,0],["v","Его в воде священной омочить —",0,928,0,0],["v","И вдруг остановился, озираясь…",0,929,0,0],["v","И замолчал. И дети и старик",0,930,0,1],["v","Смотрели на него, и весь он будто",0,930,0,0],["v","Стал сам не свой. Тревожно заходили",0,931,0,0],["v","Белки в глазах и налилися кровью,",0,932,0,0],["v","А с губ на бороду густая пена",0,933,0,0],["v","Закапала, и дикий, страшный смех",0,934,0,0],["v","Сопровождал слова его: \"Зачем же",0,935,0,0],["v","Здесь это пламя чистое? Он жив,",0,936,0,0],["v","Аргосский царь. Два раза, что ль, <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>",0,937,0,0],["v","Одну и ту же жертву приносить?",0,938,0,0],["v","Вот голову добуду Еврисфея,",0,939,0,0],["v","Тогда зараз всю пролитую кровь",0,940,0,1],["v","От рук отмою. Эти возлиянья,",0,940,0,0],["v","Корзину эту — прочь; а мне, рабы,",0,941,0,0],["v","Подайте лук со стрелами! А где же,",0,942,0,0],["v","Где палица моя? Иду в Микены;",0,943,0,0],["v","Мне ломы надобны и рычаги:",0,944,0,0],["v","Киклопы пригоняли аккуратно",0,945,0,0],["v","По ватерпасу камни, и киркой",0,945,0,0],["v","Придется, видно, стены разворочать\".",0,946,0,0],["v","Глазами колесницу стал искать;",0,947,0,0],["v","Вот будто стал на передок и машет",0,948,0,0],["v","Стрекалом. Было и смешно глядеть,",0,949,0,0],["v","И жутко нам. Давно уж меж собою",0,950,0,1],["v","Шептались мы: \"Что ж это? Шутки шутит",0,950,0,0],["v","Наш господин иль не в своем уме?\"",0,951,0,0],["v","А он, гляди, разгуливать пустился",0,952,0,0],["v","По дому, стал потом среди чертога",0,953,0,0],["v","И говорит: «Вот я теперь в Мегарах».",0,954,0,0],["v","А как попал в покои, то, как был,",0,955,0,0],["v","Разлегся на пол, завтракать собрался.",0,956,0,0],["v","Потом, немного отдохнув, решил,",0,957,0,0],["v","Что он теперь подходит к рощам Истма.",0,958,0,0],["v","Тут царь, одежду скинув, стал бороться",0,959,0,0],["v","С каким-то призраком и сам себя,",0,960,0,1],["v","Людей каких-то пригласив к вниманью,",0,960,0,0],["v","Провозгласил на играх победившим.",0,961,0,0],["v","Вот, наконец, в Микенах он: к врагу",0,962,0,0],["v","С угрозами ужасными подходит…",0,962,0,0],["v","Тут руку мощную Гераклову отец",0,963,0,0],["v","Остановил словами: \"Сын мой, что ты",0,964,0,0],["v","Затеял? Брось! Что за игра! Не кровь ли,",0,964,0,0],["v","Которую ты только что здесь пролил,",0,965,0,0],["v","Твой разум отуманила?\" Но царь",0,966,0,0],["v","Его толкает от себя, считая",0,966,0,0],["v","Отцом аргосца, что пришел молить",0,967,0,0],["v","За сына своего. Потом стрелу он",0,968,0,0],["v","На лук натянутый кладет, сбираясь",0,968,0,0],["v","Покончить с вражьими детьми, а сам",0,969,0,0],["v","В своих стал метить. Мальчики, дрожа,",0,970,0,1],["v","Врозь разбегаются: один защиты",0,970,0,0],["v","У бедной матери на лоне ищет,",0,971,0,0],["v","Тот за колонну спрятаться бежит,",0,972,0,0],["v","А третий, как испуганная птица,",0,973,0,0],["v","Дрожа, забился за алтарь. А мать",0,973,0,0],["v","Кричит: \"Опомнись, муж мой! Ты родил их,",0,974,0,0],["v","И ты ж убить их хочешь?\" Крик и стон",0,975,0,0],["v","Тут поднялись: кричит старик и слуги,",0,976,0,0],["v","А Гераклес безумною стопой",0,976,0,0],["v","Полуокружья чертит у колонны.",0,977,0,0],["v","Вот миг он уловил, — и прямо в сердце",0,978,0,0],["v","Вонзается стрела ребенку; навзничь",0,979,0,0],["v","Он падает, и мраморный устой",0,980,0,1],["v","Стены дворца он в яркий пурпур красит",0,980,0,0],["v","Своею кровью. А покуда сын",0,981,0,0],["v","Дух испускает, дикий крик победный",0,981,0,0],["v","Слетает с губ отца: \"Один птенец",0,982,0,0],["v","Готов, и тот аргосец ненавистный",0,982,0,0],["v","Часть долга кровью сына заплатил\".",0,983,0,0],["v","Затем из лука метится безумный",0,983,0,0],["v","В другого сына, что у алтаря",0,984,0,0],["v","Себя считал покуда безопасным.",0,985,0,0],["v","Ребенок, видя смерть, со ступеней",0,985,0,0],["v","Алтарных бросился к отцу, стараясь",0,986,0,0],["v","От выстрела уйти: ему на шею",0,986,0,0],["v","Повис малютка и, рукой касаясь",0,987,0,0],["v","До бороды, он молит о пощаде.",0,987,0,0],["v","\"Отец, — он говорит, — возлюбленный, меня",0,988,0,0],["v","Ты разве не узнал? Не Еврисфеев,",0,988,0,0],["v","Я твой, я твой, отец. О, пощади!\"",0,989,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span> не внемлет сыну, он ребенка",0,990,0,1],["v","Толкает от себя: он видит только,",0,990,0,0],["v","Что этой жертвы не возьмешь стрелой.",0,991,0,0],["v","И вот, блуждая озверелым взором,",0,991,0,0],["v","Он палицу над белой головенкой",0,992,0,0],["v","Взмахнул высоко, как кузнец свой молот",0,992,0,0],["v","Над наковальней поднимает, — и она",0,993,0,0],["v","Малютке череп разнесла. Покончив с этой",0,994,0,0],["v","Второю жертвой, третьего убить",0,994,0,0],["v","Он ищет. Но малютку мать успела",0,995,0,0],["v","В покои унести и заперлась.",0,995,0,0],["v","Тогда, вообразив, что это стены",0,996,0,0],["v","Киклоповой работы, Гераклес",0,997,0,0],["v","Свой дом буравить начинает, стены",0,997,0,0],["v","Свои ломает; бешеных ударов",0,998,0,0],["v","Не выдержали двери: через миг",0,998,0,0],["v","<span class=\"ch\" data-ch=\"megara\">Мегара</span> и малютка с ней одною",0,999,0,0],["v","Стрелой пронизаны лежат… За старцем",0,1000,0,1],["v","Погнался царь, да бог не допустил.",0,1000,0,0],["v","Явился образ величавый, и признали",0,1001,0,0],["v","Афину тотчас мы: она легко",0,1002,0,0],["v","Копьем медноконечным потрясала,",0,1003,0,0],["v","Его сжимая в шуйце. Прямо в грудь",0,1003,0,0],["v","Богиня бросила огромный камень",0,1004,0,0],["v","Безумному царю и злодеянья",0,1005,0,0],["v","Десницею остановила властной…",0,1006,0,0],["v","Царь наземь рухнулся, и крепкий сон",0,1006,0,0],["v","Его сковал немедля. А спиною",0,1007,0,0],["v","Как раз излом колонны он покрыл,",0,1008,0,0],["v","Что городила двор среди погрома.",0,1009,0,0],["v","Приободрились мы тогда, и, вместе",0,1010,0,1],["v","С <span class=\"ch\" data-ch=\"amfitrion\">Амфитрионом</span> подойдя к царю,",0,1010,0,0],["v","Его мы путами и поясами крепко",0,1011,0,0],["v","К обломку прикрутили, чтоб потом,",0,1012,0,0],["v","Когда проснется, новых бед каких",0,1013,0,0],["v","Не натворил. Несчастный сном тяжелым",0,1013,0,0],["v","Спит и теперь. Да, он детей убил,",0,1014,0,0],["v","Жену убил, — но равных с ним страданий",0,1015,0,0],["v","Здесь, на земле, не испытал никто.",0,1016,0,0],["scene","Четвертый музыкальный антракт","s17",5,17],["sp","Хор"],["v","Было и раньше страшное дело:",0,1016,0,0],["v","Мужей Данаиды убили, —<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,1017,2,0],["v","Эллада поверить не смела тогда",0,1018,0,0],["v","Тому, что аргосские стены узрели.",0,1019,0,0],["v","Но ужаса больше внушает мне доля",0,1020,0,1],["v","Несчастного Зевсова сына.",0,1020,2,0],["v","Кровавое дело иное",0,1021,2,0],["v","Могу я поведать,",0,1021,2,0],["v","Как Прокна сына убила",0,1022,2,0],["v","Единого, Музам;",0,1022,2,0],["v","Звучат и поднесь",0,1023,2,0],["v","Ее тоскливые песни,",0,1023,2,0],["v","Но ты, но ты, от которого бог отступился,",0,1024,0,0],["v","Не трех ли убил ты, тобою рожденных?",0,1024,0,0],["v","Не трех ли, беснуясь,",0,1025,2,0],["v","На землю детей уложил?",0,1025,2,0],["v","Увы мне! Увы мне! Увы мне!",0,1026,0,0],["v","Где слез наберу я оплакать тебя?",0,1026,0,0],["v","Где песен надгробных?",0,1027,2,0],["v","Где плясок для тризны?",0,1027,2,0],["act","Исход","a6",""],["scene","Явление тринадцатое","s18",6,18],["sd","Во время первых слов хора ворота дворца распахиваются, виден двор и внутренность дома. На первом плане, среди общего разгрома, виден обломок колонны, а на нем спит связанный и прикрученный к камню <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>; около него брошены лук и колчан и рассыпаны стрелы. Дальше трупы <span class=\"ch\" data-ch=\"megara\">Мегары</span> с ребенком на груди и двух мальчиков. В глубине сцены <span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>."],["sp","Хор"],["v","Га!",0,1028,0,0],["v","Смотрите! смотрите!",0,1028,0,0],["v","Подалися створки,",0,1029,0,0],["v","И настежь открылись",0,1029,0,0],["v","Ворота высоких чертогов.",0,1030,0,1],["v","О, ужас! О, горе!",0,1031,0,0],["v","Вот, вот они, дети,<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,1032,0,0],["v","Лежат и не дышат",0,1033,0,0],["v","В ужасном соседстве",0,1034,0,0],["v","С убийцей-отцом.",0,1035,0,0],["v","А он-то как страшен,",0,1036,0,0],["v","Осиленный кровью сыновней,",0,1037,0,0],["v","Распялен на камне колонны!",0,1038,0,0],["sp","Корифей"],["v","Вот и старик: стопой неверной он",0,1039,0,0],["v","Едва бредет под грузом лет и горя;",0,1040,0,1],["v","Так птица отлететь не хочет от гнезда",0,981,0,0],["v","Разбитого и все по мертвым стонет.",0,922,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","приближаясь"],["v","Тише, тише, фиванские старцы!<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,862,0,0],["v","Пусть, развязанный сном,",0,803,0,0],["v","Он забвенье вкушает.",0,744,0,0],["sp","Хор"],["v","Мои слезы, мои вздохи<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,684,0,0],["v","Все тебе, мой старый вождь.",0,625,0,0],["v","Все твоим прекрасным внукам",0,566,0,0],["v","И, венчанному победой,",0,506,0,0],["v","Твоему герою-сыну!<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,447,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ах, отойдите!<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,388,0,0],["v","Шумом и криком своим",0,328,0,0],["v","Сына разбудите…",0,269,0,0],["v","Весь он размаялся,",0,210,0,0],["v","Сладко так спит он.",0,150,0,1],["sp","Хор"],["v","Крови-то, крови-то, господи!",0,151,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Сжальтеся, сжальтесь над старцем!",0,152,0,0],["sp","Хор"],["v","Крови-то пролито!",0,153,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Тише вы, тише вы, старцы-соратники!",0,154,0,0],["v","Разве не можете",0,155,3,0],["v","Плакать без голоса?",0,156,3,0],["v","Будет нам всем беда,",0,157,3,0],["v","Если проснется сын:",0,158,3,0],["v","С камня-то прянет,",0,159,3,0],["v","Путы порвет;",0,160,3,0],["v","Всех перебьет тогда,",0,161,3,0],["v","В груду развалин",0,162,3,0],["v","Город сметет…",0,163,3,0],["sp","Хор"],["v","Сил моих, сил моих нет молчать.",0,164,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Стойте вы там!",0,165,4,0],["v","Ухо к груди его",0,166,4,0],["v","Дайте приблизить мне.",0,167,4,0],["v","Спит ли он?",0,168,4,0],["v","Спит ли ж он?",0,169,4,0],["sd","(Подходит к <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> и приклоняется к его груди.)"],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["sp","Хор"],["v","Спит ли он?",0,1060,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Спит он… Но как?",0,1060,0,0],["v","Сном он кровавым спит,",0,1061,0,0],["v","Дремой греховною…",0,1061,0,0],["v","Спит, а во сне",0,1062,0,0],["v","С жилы натянутой",0,1063,0,0],["v","Стрелы срываются,",0,1063,0,0],["v","Свищут и смерть несут,",0,1064,0,0],["v","Матери, детям смерть…",0,1065,0,0],["sp","Хор"],["v","Плачь же!",0,1065,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","О, плачу я.",1,1065,0,0],["sp","Хор"],["v","Внуков оплачь!",0,1066,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Бедные, горькие…",1,1066,0,0],["sp","Хор"],["v","Сына…",0,1066,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ох, плачу я!",1,1066,0,0],["sp","Хор"],["v","Старец!",0,1067,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Постойте же вы! Видите! видите!",0,1068,0,0],["v","Вот заворочался! вот головой затряс!",0,1068,0,0],["v","Приподнимается! Боги, проснулся он…",0,1069,0,0],["v","Спрячь меня, спрячь, дворец!",0,1070,0,1],["sd","(С движением, по направлению от <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>.)"],["sp","Хор"],["v","Бог с тобой! Ночь еще",0,1070,0,0],["v","Сонным забвением",0,1071,0,0],["v","Сына объемлет, ночь…",0,1071,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Не за себя боюсь,",0,1072,1,0],["v","Старцы-соратники;",0,1072,1,0],["v","Жалкий старик,",0,1073,1,0],["v","Смерти ль бояться мне?",0,1074,1,0],["v","Но если он снова начнет",0,1074,0,0],["v","Убийства… но если,",0,1075,0,0],["v","Отцовской кровью запятнан,",0,1075,0,0],["v","Все глубже, все дальше",0,1076,0,0],["v","В пучину нечестья…",0,1077,0,0],["sp","Хор"],["v","О, для чего пережил ты",0,1077,0,0],["v","День, когда город тафийцев,",0,1078,0,0],["v","Весь окруженный водою,",0,1078,0,0],["v","Мстя за жениных братьев,",0,1079,0,0],["v","Дланью могучей ты рушил?",0,1080,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Старцы!",0,1080,3,0],["v","Я заклинаю вас, не оставайтесь здесь…",0,1081,0,0],["v","Бешеный поднялся, кровь его душит, кровь…",0,1082,0,0],["v","Будет он жертв искать,",0,1083,3,0],["v","Вихрем безумия",0,1084,3,0],["v","Фивы охватит он…",0,1085,3,0],["sp","Корифей"],["v","О Зевс, к чему весь этот гнев? Зачем",0,1086,0,0],["v","В такое море слез ты гонишь сына?",0,1087,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","открывает глаза и говорит медленно"],["v","Га…",0,1088,0,0],["v","Я жив еще. О Гелиос, опять",0,1089,0,0],["v","В твоем сиянье и земля и небо",0,1090,0,1],["v","Передо мной… Но точно… жаркий ветер",0,1090,0,0],["v","Пустыни… опалил мне душу… Горячо",0,1091,0,0],["v","Дыханье, воздух вырывается из легких",0,1092,0,0],["v","Неровно так… А сам-то?.. Как корабль,",0,1093,0,0],["v","Прикрученный канатами… Смотрите:",0,1094,0,0],["v","Веревкой спутаны и грудь и руки… Что…",0,1095,0,0],["v","Что подо мною здесь? Обломок",0,1095,0,0],["v","Расколотой колонны. А? А это?",0,1096,0,0],["v","А это что вокруг меня? Тела",0,1097,0,0],["v","Убитых. Брошен лук… Вот стрелы",0,1098,0,0],["v","Рассыпаны… Я так их берегу:",0,1099,0,0],["v","Они — моя защита лучшая… Да где ж я?",0,1100,0,1],["v","Опять в аду? Быть может, Еврисфей",0,1100,0,0],["v","Меня сослал туда вторично?.. Только",0,1100,0,0],["v","Где ж тут тогда Сизифов камень? Нет,",0,1100,0,0],["v","Здесь Персефона не царит. Так где ж я?..",0,1100,0,0],["v","Эй, люди добрые, скажите, где я?",0,1100,0,0],["v","Туманом ум закутан мой. Ужели",0,1100,0,0],["v","Никто не исцелит его? Узнать",0,1100,0,0],["v","Привычных образов я не могу. Да где ж я?..",0,1100,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","подвигаясь к <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>"],["v","Дерзну ли к горькому приблизиться?",0,1100,0,0],["sp","Корифей"],["dir","с хором тоже подступая к <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>"],["v","Иду с тобой, не брошу друга в горе.",0,1100,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","узнав <span class=\"ch\" data-ch=\"amfitrion\">Амфитриона</span>"],["v","Отец! Ты плачешь? Ты лицо закрыл?",0,1101,0,0],["v","Ты к сыну будто подойти боишься?",0,1102,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","О мой <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>! Оплаканный, все ж мой!",0,1103,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Оплаканный? А горе? Где же горе?",0,1104,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Сам бог слезу бы пролил над тобой.",0,1105,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Сам бог — легко сказать! Да в чем же дело?",0,1106,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Сам видишь, если уж пришел в себя.",0,1107,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Во мне что новое открыл, отец, ты? Что же?",0,1108,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Скажи нам, ты совсем пришел в себя?",0,1121,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Уклончивый ответ таит несчастье.",0,1120,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Коль бес тебя уж перестал терзать…",0,1119,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Так бесновался я? Совсем не помню.",0,1120,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Я развяжу <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>, старики?",0,1121,0,0],["sd","(Подходит и распутывает узы <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>; тот садится на камень.)"],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","А кто ж вязал меня? О, как мне стыдно!",0,1122,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Что знаешь — знай. Об остальном молчи.",0,1123,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты ж молча объяснишь мне все, не так ли?",0,1124,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ты с ложа Геры видишь нас, Кронид?",0,1125,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты назвал Геру… Месть ее все длится?",0,1126,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","строго"],["v","Оставь богов! Иль мало зол своих?",0,1127,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Зол, говоришь ты? Разве я преступник?",0,1130,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ты эти трупы, сын мой, узнаешь?",0,1131,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","всматривается в трупы"],["v","О, горе мне! О, горе! Дети… Дети…",0,1132,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Да, детский труп, мой сын, — плохой трофей.",0,1133,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты говоришь — трофей? Но кто ж убил их?",0,1134,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Ты, лук твой и желавший смерти бог.",0,1135,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Я их убил?.. Как? Как? О, вестник бедствий!",0,1136,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Беснуясь. Слишком страшно все раскрыть.",0,1137,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Жены, Мегары, тоже я убийца?",0,1138,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Весь этот ужас — дело рук твоих.",0,1139,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Какою тучей скорби я окутан!",0,1140,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Я плачу над тобой, мой бедный сын.",0,1141,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но где ж, отец, когда беда стряслася?",0,1144,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","У алтаря, при очищенье рук.",0,1145,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","А дом кто рушил? Тоже я, беснуясь?",0,1142,0,1],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Чего ж ты ждешь еще? Ответ один:",0,1142,0,0],["v","Повсюду разлито твое несчастье.",0,1143,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Я это слушаю, и я еще живу?",0,1146,0,1],["v","Ждет счастия детоубийца, видно!",0,1147,0,0],["v","Зачем с утеса в море не спрыгну я,",0,1148,0,0],["v","Чего я медлю в сердце меч вонзить,",0,1149,0,0],["v","Как следует судье и мстителю?",0,1150,0,1],["v","Что держит это тело? Что мешает",0,1150,0,0],["v","Ему в огне спастися от бесчестья,",0,1151,0,0],["v","Жизнь заменившего <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>?.. Что?",0,1152,0,0],["sd","(Хочет идти и видит приближающегося <span class=\"ch\" data-ch=\"tesey\">Тесея</span>.)"],["v","Ба… остановка для расчета с жизнью…",0,1153,0,0],["v","Сюда <span class=\"ch\" data-ch=\"tesey\">Тесей</span> идет, мой лучший друг,",0,1153,0,0],["v","Сейчас нечистого детоубийцу",0,1154,0,0],["v","Увидят, и увидит человек,",0,1155,0,0],["v","Который был так близок мне. Проклятье!",0,1156,0,0],["v","Ни небу, ни земле меня не скрыть",0,1156,0,0],["v","Теперь от взоров этого пришельца;",0,1157,0,0],["v","Пускай же ночь <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> осенит",0,1158,0,0],["v","Хоть голову… Как будто мало муки,",0,1159,0,0],["v","Позора за содеянное зло.",0,1160,0,1],["v","Я запятнал свой дом… Иль надо друга",0,1160,0,0],["v","Детоубийце взглядом осквернять?",0,1161,0,0],["sd","(Закрывает плащом лицо.)"],["scene","Явление четырнадцатое","s19",6,19],["sd","Те же и <span class=\"ch\" data-ch=\"tesey\">Тесей</span>,в походной одежде и с копьем. С ним небольшая свита."],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Амфитрион! Я прихожу на помощь",0,1162,0,0],["v","К <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>, а отряд вооруженный",0,1163,0,0],["v","Афинских юношей оставил у реки…",0,1164,0,0],["v","Мы получили весть, что без <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>",0,1165,0,0],["v","Здесь <span class=\"ch\" data-ch=\"lik\">Лик</span> у вас престолом завладел",0,1166,0,0],["v","Насильно. И немедля я решился",0,1167,0,0],["v","Услугою <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> отплатить",0,1168,0,0],["v","За то, что он меня из преисподней",0,1169,0,0],["v","На божий свет вернул. Так если только",0,1170,0,1],["v","Полезна вам моя рука иль войско…",0,1170,0,0],["v","Ба…<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,1171,0,0],["v","Но что же это? Перед домом трупы!",0,1172,0,0],["v","Иль опоздал прийти я и уже",0,1173,0,0],["v","Неслыханное дело совершилось?",0,1173,0,0],["v","Вот дети! Кто ж убил их? Вот жена, —",0,1174,0,0],["v","Кто мужем был ей? Только не сраженье",0,1175,0,0],["v","Происходило здесь. Малютки разве",0,1176,0,0],["v","В боях участвуют? Нет, здесь следы",0,1176,0,0],["v","Иного и ужасного злодейства.",0,1177,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Увы мне, владыка скалистого града оливы!<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,1178,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Зачем ты говоришь «увы», старик?",0,1179,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Нам боги послали ужасную кару.",0,1180,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Чьи ж дети здесь оплаканы тобой?",0,1180,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Их сын мой посеял, несчастнейший смертный,",0,1181,0,0],["v","И он же убийца, их кровью покрытый.",0,1182,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Молчи, молчи! Что говоришь ты, старец?",0,1183,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","О, если бы неправду я сказал!",0,1184,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ужасное известье!",0,1185,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Погибли мы, афинский царь, погибли!",0,1186,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Убил-то как он их?",0,1187,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Железом.",1,1187,0,0],["v","Железом палицы и ядом стрел.",0,1188,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Зачем, старик, зачем?",0,1189,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Удар безумья.",1,1189,0,0],["v","Безумья весел плеск по влаге жизни.",0,1190,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Все Геры месть. Но кто же это там,<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,1190,0,0],["v","Старик, сидит меж трупов?",0,1191,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Сын мой,",1,1191,0,0],["v","То сын мой с своей несказанною мукой,",0,1192,0,0],["v","Когда-то соратник богов",0,1192,1,0],["v","На выжженных нивах Гигантов…",0,1193,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, боги! Гонений судьбы",0,1194,0,0],["v","Кто более вынести мог бы?",0,1195,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Никто, о Тесей, на земле",0,1195,0,0],["v","Таких испытаний не встретил,",0,1196,0,0],["v","И дикие вихри такие",0,1197,0,0],["v","Из смертных никем не играли…",0,1197,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Зачем же голову победную накрыл он?",0,1198,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Стыдится тебя он, Тесей,",0,1199,0,0],["v","Стыдится и старцев фиванских.",0,1200,0,1],["v","А пуще детей он стыдится,",0,1200,0,0],["v","Их крови, что пролил.",0,1201,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Открой его: мы вместе будем плакать.",0,1201,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["dir","подходя к сыну, который сидит на камне неподвижно, с покрытой головой"],["v","Дитя мое, сын мой!",0,1202,1,0],["v","Спусти покрывало",0,1203,1,0],["v","И тьму от очей удали:",0,1203,1,0],["v","Пусть солнце лицо твое видит.",0,1204,1,0],["v","Ты слез не стыдися. Смотри, как я плачу.",0,1205,1,0],["v","Неужто за слезы отца",0,1205,1,0],["v","Ты стыд не отдашь свой?",0,1206,1,0],["v","Смотри, я к коленям припал,",0,1206,0,0],["v","С мольбою ловлю твою руку,",0,1207,0,0],["v","Щеки я касаюсь и плачу.",0,1208,0,0],["v","Пусть слезы мои,",0,1208,0,0],["v","Струяся с ресниц поседевших,",0,1209,0,0],["v","Смягчат твою ярость,",0,1210,0,1],["v","Пусть ей не дадут",0,1210,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> увлечь по кровавой стезе",0,1211,0,0],["v","К убийствам,",0,1212,2,0],["v","Дитя мое, сын мой.",0,1213,1,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","тоже подходя к <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span>, который сидит неподвижно"],["v","Пора, Геракл! Не век же, в самом деле,",0,1213,0,0],["v","На ложе слез тебе сидеть и плакать.",0,1214,0,0],["v","Открой лицо и другу отзовись!",0,1215,0,0],["v","Несчастья все равно не скроешь: тучи",0,1216,0,0],["v","Такой, такого мрака не найдешь.",0,1216,0,0],["v","Ты боязливо руку отстраняешь",0,1217,0,0],["v","Мою. Иль, даже говоря с тобой,",0,1218,0,0],["v","Себя я оскверняю? Нет, <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>.",0,1219,0,0],["v","Делить несчастье друга не боюсь я.",0,1220,0,1],["v","Пусть в счет идет теперь тот день, когда",0,1220,0,0],["v","Меня на землю вывел ты из мрака",0,1221,0,0],["v","Поддонного. Та дружба, что ветшает,",0,1222,0,0],["v","Мне ненавистна. Как? У друга за столом",0,1223,0,0],["v","Отведав брашен сладких, в дни невзгоды",0,1224,0,0],["v","Его корабль покинуть? Встань, герой,",0,1225,0,0],["v","И, голову несчастную открыв,",0,1226,0,0],["v","В лицо взгляни мне. Благородный муж",0,1227,0,0],["v","Удар судьбы перенесет без жалоб.",0,1228,0,0],["sd","(Открывает его.)"],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты, царь, детей моих уж видел трупы?",0,1229,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Все видел я и обо всем узнал.",0,1230,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Узнал — и хочешь, чтоб на свет глядел я?",0,1230,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А отчего ж бы нет? Ты — смертный муж,",0,1231,0,0],["v","И мира божьего ты осквернить не можешь.",0,1232,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Беги от язвы, смертный, от проклятья!",0,1233,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Проклятьем друг не будет мне, <span class=\"ch\" data-ch=\"gerakl\">Геракл</span>.",0,1234,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Да. Точно, зла ты от меня не видел.",0,1235,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ты спас меня, дай мне страдать с тобою.",0,1236,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Мне надо много, много состраданья…",0,1237,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Несчастный друг и страшная судьба!",0,1238,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Тесей, ты видел смертных в большем горе?",0,1239,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Нет, до небес главою скорбь твоя.",0,1240,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Так знай, ее сейчас со мной не будет.",0,1241,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Иль похвальбой ты пригрозишь богам?",0,1242,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Богам? Нам дела нету друг до друга.<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,1243,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Молчи, больнее падать с высоты…",0,1244,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Наполнен кубок, через край уж льется.",0,1245,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Скажи, куда же гнев тебя влечет?",0,1246,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Опять в Аид, на этот раз уж трупом.",0,1247,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Обычный выход черни — в сердце нож.",0,1248,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Сентенция умов самодовольных!",0,1249,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И это ты, великий Гераклес,",0,1250,0,1],["v","Подъявший столько тяжких испытаний!.",0,1250,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Но не таких! И испытанью — мера…",0,1251,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","не слушая его"],["v","Защитник, неизменный друг людей…",0,1252,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","А люди защитят меня от Геры?",0,1253,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Так именем Эллады говорю",0,1254,0,0],["v","Тебе: оставь безумную затею!",0,1255,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","вставая с камня"],["v","Нет, прежде выслушай меня, Тесей!",0,1255,0,0],["v","Я докажу тебе, что право жить",0,1256,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span> уж потерял. Начнем с рожденья.",0,1257,0,0],["v","От корня я греховного: отец,",0,1258,0,0],["v","Не смывши крови тестя старого, поял",0,1259,0,0],["v","Алкмену в жены. Дети отвечают",0,1260,0,1],["v","За ненадежные устои дома. Зевс",0,1260,0,0],["v","Всходил на ложе брачное Алкмены.",0,1261,0,0],["v","Да, — Зевс, <span class=\"ch\" data-ch=\"tesey\">Тесей</span>. А ты, Амфитрион,",0,1262,0,0],["v","На сына не сердись: тебе всецело",0,1263,0,0],["v","Принадлежит сыновняя любовь.",0,1264,0,0],["v","От Зевса только ненависть супруги",0,1265,0,0],["v","Его я получил. Еще у груди",0,1265,0,0],["v","Я был, когда она мне в колыбель",0,1266,0,0],["v","Послала змей с горящими глазами.",0,1267,0,0],["v","А с той поры, когда вошел я в силу,",0,1268,0,0],["v","С дней юности… иль надо исчислять",0,1269,0,0],["v","Труды подъятые? тех львов, Гигантов,",0,1270,0,1],["v","Тех пламя изрыгающих чудовищ,",0,1270,0,0],["v","Стада кентавров тех четвероногих,",0,1271,0,0],["v","Что избивать я должен был? Змею,",0,1272,0,0],["v","То чудище стоглавое, что вечно",0,1272,0,0],["v","Растило головы взамен отбитых,",0,1273,0,0],["v","Я должен был осилить… Целый ряд, —",0,1274,0,0],["v","Неисчислимые труды замкнулись",0,1275,0,0],["v","Сошествием в юдоль теней, откуда",0,1275,0,0],["v","Я сторожа в воротах смерти, пса",0,1276,0,0],["v","О трех телах, из мрака вывел к свету.",0,1277,0,0],["v","Так Еврисфей мне приказал… Но вот",0,1277,0,0],["v","Предельный подвиг мой, Тесей, — ты видишь",0,1278,0,0],["v","Тела убитых мной детей: то камень",0,1279,0,0],["v","Последний в здании моих несчастий.",0,1280,0,1],["v","Такой бедой придавленный, могу ль",0,1280,0,0],["v","Убийцей я остаться в милых Фивах?",0,1281,0,0],["v","А если б и остался, то дерзну ль",0,1281,0,0],["v","Я в храм войти или к друзьям, на праздник",0,1282,0,0],["v","Идущим, присоединиться? Нет, Тесей,",0,1283,0,0],["v","Проклятье, надо мной висящее,",0,1283,0,0],["v","Людей страшить должно. Нельзя и в Аргос",0,1284,0,0],["v","Изгнаннику. Так дальше на чужбину,",0,1285,0,0],["v","Быть может? Да, чтобы встречать повсюду",0,1285,0,0],["v","Взгляд неприязненный и ненависть?",0,1286,0,0],["v","<span class=\"ch\" data-ch=\"gerakl\">Геракла</span> всюду знают. Каково",0,1286,0,0],["v","Услышать, как надменный чужестранец,",0,1287,0,0],["v","Указывая на тебя, промолвит:",0,1288,0,0],["v","\"А, это тот <span class=\"ch\" data-ch=\"gerakl\">Геракл</span> и сын Зевеса,",0,1288,0,0],["v","Который перебил свою семью.",0,1289,0,0],["v","Пусть уходил бы он куда подальше!\"",0,1290,0,1],["v","А ведь тому, кто счастие познал,",0,1290,0,0],["v","Его измена нестерпима; легче",0,1291,0,0],["v","Выносит горе, кто к нему привык.",0,1292,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ведь до того дойдет, что уж не люди,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,1293,0,0],["v","А реки, море, земли закричат:",0,1294,0,0],["v","«Назад: не смей касаться нас, несчастный!»",0,1295,0,0],["v","Что ж, или обратиться напоследок",0,1295,0,0],["v","Мне в Иксиона, с вечным колесом",0,1296,0,0],["v","Из пламени, которое он крутит?",0,1297,0,0],["v","А коль мне это рок сулит — пусть лучше",0,1298,0,0],["v","Меня никто из эллинов не видит",0,1299,0,0],["v","Из тех, что знали в счастии меня.",0,1300,0,1],["v","И все-таки я должен жить? Да жизнь-то",0,1300,0,0],["v","Под бременем проклятья разве — жизнь?",0,1301,0,0],["v","Нет, пусть она теперь, светлейшая",0,1302,0,0],["v","Супруга олимпийца, танец свой",0,1302,0,0],["v","Победный пляшет там, на горной выси",0,1303,0,0],["v","Зевесовой, и под ее стопой",0,1304,0,0],["v","Гора дрожит! Свершилась воля Геры:",0,1305,0,0],["v","Эллады первый муж низвергнут, дом",0,1305,0,0],["v","Его в обломках, срыт до основанья…",0,1306,0,0],["v","И это — бог… Молиться могут ей…",0,1307,0,0],["v","Из ревности к какой-то смертной, мужа",0,1307,0,0],["v","Красой привлекшей, мстит она тому,",0,1308,0,0],["v","Кто эллинам оградой был, спасал их;",0,1309,0,0],["v","И чью ж вину он должен искупать?",0,1310,0,1],["sp","Корифей"],["v","Да, это верно: все твое несчастье",0,1310,0,0],["v","От Геры, а не от других богов.",0,1311,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Не спорю: легче требовать терпенья,",0,1312,0,0],["v","Чем самому терпеть от рук судьбы.",0,1312,0,0],["v","Но где тот человек, тот бог, скажи мне,",0,1313,0,0],["v","Который бы греха не зная жил?",0,1314,0,0],["v","Послушаешь поэтов, что за браки",0,1315,0,0],["v","Творятся в небе беззаконные!",0,1315,0,0],["v","А разве не было, скажи мне, бога,",0,1316,0,0],["v","Который, в жажде трона, над отцом",0,1317,0,0],["v","Ругаясь, заковал его? И что же?",0,1317,0,0],["v","Они живут, как прежде, на Олимпе,",0,1318,0,0],["v","И бремя преступлений не гнетет их.",0,1319,0,0],["v","Так как же смеешь ты, ничтожный смертный,",0,1320,0,1],["v","Невыносимой называть судьбу,",0,1320,0,0],["v","Которой боги подчиняются? Ты в Фивах,<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1321,0,0],["v","Обычаю покорный, жить не должен.",0,1322,0,0],["v","Но в град Паллады ты войдешь за мной;",0,1323,0,0],["v","От крови пролитой очистив руки,",0,1324,0,0],["v","Я дам тебе приют и прокормлю:",0,1325,0,0],["v","Дары, которыми афиняне почтили",0,1326,0,0],["v","Меня за критского быка, и дважды семь<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1327,0,0],["v","Детей, спасенных мной, — они твои.",0,1328,0,0],["v","Имения мои — по всей стране: покуда",0,1329,0,0],["v","Живешь ты, ты — хозяин полный их.",0,1330,0,1],["v","Когда же смерть тебя в юдоль Аида",0,1330,0,0],["v","Опустит, алтарем почетным, жертвой",0,1331,0,0],["v","Почтит героя весь афинский край.",0,1332,0,0],["v","Наградой же Афин достойной будет",0,1333,0,0],["v","Та слава, что в Элладе мы пожнем",0,1334,0,0],["v","За помощь мужу славному в несчастье,<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1335,0,0],["v","Позволь и личный долг мне уплатить:",0,1336,0,0],["v","Надежный друг теперь <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> нужен.",0,1337,0,0],["v","Когда же бог возносит нас — к чему",0,1338,0,0],["v","Друзья? Довольно благостыни бога…",0,1339,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Увы, Тесей, меня в моей печали",0,1340,2,1],["v","Теперь игра ума не веселит…",0,1340,2,0],["v","К тому же я не верил и не верю,",0,1341,2,0],["v","Чтоб бог вкушал запретного плода,",0,1342,2,0],["v","Чтоб на руках у бога были узы",0,1343,2,0],["v","И бог один повелевал другим.",0,1343,2,0],["v","Нет, божество само себе довлеет:",0,1344,2,0],["v","Все это бредни дерзкие певцов.",0,1345,2,0],["v","Довольно… Я не скрою, что сомненьем",0,1346,3,0],["v","Теперь охвачен я, не точно ль трус",0,1346,2,0],["v","Самоубийца…",0,1347,2,0],["sd","(В раздумье.)"],["v","Да, кто не умеет",0,1348,4,0],["v","Противостать несчастью, тот и стрел",0,1349,2,0],["v","Врага, пожалуй, испугается… Я должен",0,1350,2,1],["v","И буду жить… С тобой, Тесей, пойду",0,1350,2,0],["v","В Афины. Как тебя благодарить",0,1351,2,0],["v","За дружбу и подарки, я не знаю.",0,1352,2,0],["v","Я вынес тысячи трудов и мук,",0,1353,2,0],["v","Я без числа вкусил, не отказавшись",0,1353,2,0],["v","Ни от одной, и никогда из глаз",0,1354,2,0],["v","Моих слеза не падала. Не думал,",0,1355,2,0],["v","Что мне придется плакать, но судьбе",0,1356,2,0],["v","Теперь, как раб, я повинуюсь.",0,1356,2,0],["sd","(Плачет, потом к отцу.)"],["v","Старец,",0,1357,4,0],["v","Я ухожу в изгнанье. Я — убийца",0,1358,2,0],["v","Своих детей; возьми их, о отец,",0,1359,2,0],["v","И схорони, почти слезой надгробной:",0,1360,2,1],["v","Любви услугу эту я не смею",0,1360,2,0],["v","Им оказать. Ты положи детей",0,1361,2,0],["v","На грудь их матери, ты их отдай ей:",0,1362,2,0],["v","Пусть вместе и покоятся, как вместе",0,1363,2,0],["v","Убил их я неволей. В Фивах ты",0,1364,2,0],["v","Останься жить; хоть трудно, да смирись,",0,1365,2,0],["v","Неси со мной, отец, мое несчастье.",0,1366,2,0],["sd","(Подходит к трупам детей и жены с прощаньем.)"],["v","Вы, дети, мной рожденные и мной же",0,1367,2,0],["v","Убитые! Всю жизнь трудился я,",0,1368,2,0],["v","Чтоб вам оставить лучшее наследство,",0,1369,2,0],["v","Какое детям оставляют, — имя.",0,1370,2,1],["v","Но вы отцовской славы не вкусили.",0,1370,2,0],["v","Прости и ты, жена, убийце. Плохо",0,1371,2,0],["v","Вознаградил тебя твой муж за то,",0,1372,2,0],["v","Что с робким и упорным постоянством",0,1372,2,0],["v","Ему ты ложе чистым берегла,",0,1373,2,0],["v","И столько лет… Моя <span class=\"ch\" data-ch=\"megara\">Мегара</span>, дети!",0,1374,2,0],["v","Вам, мертвым, горе, горе и убийце!",0,1375,2,0],["v","О, дайте ж перед вечным расставаньем",0,1375,2,0],["v","С лобзанием последним к вам прижаться!",0,1376,2,0],["v","Как горек этот сладкий поцелуй,",0,1377,2,0],["sd","(плача, целует мертвых)"],["v","Я длю его… А вот и лук… Как тяжко",0,1377,2,0],["v","Его мне видеть… Брать или не брать?",0,1378,2,0],["v","Он при ходьбе, стучась о бок, мне скажет:",0,1379,2,0],["v","\"Ты мной убил жену и сыновей,",0,1380,2,1],["v","Ты носишь на плече убийцу кровных\".",0,1380,2,0],["v","Не брать?.. Но как же бросить тот доспех,",0,1381,2,0],["v","С которым подвиг я свершил славнейший",0,1382,2,0],["v","Из всех, в Элладе виданных, себя ж,",0,1383,2,0],["v","Владельца стрел, обречь бесславной смерти",0,1383,2,0],["v","От вражеской руки?..",0,1384,2,0],["sd","(Берет лук и собирает в колчан стрелы.)"],["v","Товарищ бранный,",0,1385,4,0],["v","Носить тебя, страдая, но носить!",0,1386,2,0],["v","А ты, Тесей, мне помоги теперь",0,1386,2,0],["v","Свести к царю Кербера, не отважусь",0,1387,2,0],["v","Идти один, тоской совсем измучен…",0,1388,2,0],["v","Вас напоследок, Фивы, я зову",0,1389,2,0],["v","Сюда, народ кадмейский: остригитесь,",0,1390,2,1],["v","Наденьте траур и на погребенье",0,1390,2,0],["v","Детей моих придите: плачь, стенай,",0,1391,2,0],["v","Земля фиванская, по мертвых и живом,",0,1392,2,0],["v","Всех Гера нас в один связала узел.",0,1393,2,0],["sd","(Садится опять на камень.)"],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Приподнимись, несчастный. Будет плакать!",0,1394,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Как камень ноги. Сил не соберу.",0,1395,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Что? Видно, и могучих ломит горе.",0,1395,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Я камень, камень… Как забыть я мог?",0,1396,0,0],["v","О горе!",0,1397,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Не плачь, мой бедный друг, и дай мне руку.",0,1398,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты осквернишься: вся рука в крови.",0,1399,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Смелей бери! я не боюся скверны.",0,1400,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Бездетному ты точно добрый сын…",0,1400,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Идем, Геракл, берись за плечи друга.",0,1401,0,0],["sd","(Приподнимает <span class=\"ch\" data-ch=\"gerakl\">Геракла</span>.)"],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ты — верный, я ж, Тесей, — несчастный друг.",0,1402,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","беря его за плечи, подвигает к выходу"],["v","Вперед! Я поделюсь с тобою счастьем.<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1403,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Отец, видал ли ты таких, как он?",0,1404,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Да, счастлив город, что растит подобных!",0,1405,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Постой, Тесей, постой!",0,1405,0,0],["v","Дай кинуть взгляд прощальный на детей.",0,1406,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Иль сердца боль от этого смягчится?",0,1407,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["dir","направляясь к отцу"],["v","К груди отца прижаться дай, Тесей!",0,1408,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","О сын мой, дай обнять тебя и старцу!",0,1409,0,0],["sd","(Обнимает его; плачут оба.)"],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Где подвиги твои, герой, где стойкость?",0,1410,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Всех подвигов мне скорбь моя трудней.",0,1410,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Но женщиной <span class=\"ch\" data-ch=\"gerakl\">Гераклу</span> быть не должно.",0,1411,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Меня таким ты раньше ведь не знал?",0,1412,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Да, в горе ты не прежний славный воин.",0,1413,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","А ты в аду такой же стойкий был?",0,1414,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Нет, я упал там духом, как ребенок.",0,1415,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Ну, значит, и меня теперь поймешь.",0,1415,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Вперед!",0,1416,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Прощай, отец.",0,1417,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Прости мне, сын мой!",1,1417,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Похорони ж детей, как я просил.",0,1418,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","А кто же мне закроет очи?",0,1419,0,0],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Сын твой.",1,1419,0,0],["sp","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span>"],["v","Назад-то ждать когда тебя?",0,1420,0,1],["sp","<span class=\"ch\" data-ch=\"gerakl\">Геракл</span>"],["v","Сперва",1,1420,0,0],["v","Детей похорони. Тогда вернусь",0,1421,0,0],["v","И увезу тебя с собой в Афины.",0,1422,0,0],["v","Тела-то убери, тяжелый труд",0,1423,0,0],["v","Тебе я оставляю. Слез-то, слез-то!",0,1424,0,0],["v","Меня же, отягченного злодейством,",0,1425,0,0],["v","Позорно дом сгубившего, Тесей,",0,1426,0,0],["v","Как барку грузную, отсюда тащит…",0,1427,0,0],["v","Глупец, кто ценит здесь богатство, силу:",0,1428,0,0],["v","Дороже всех даров — надежный друг.",0,1429,0,0],["sd","(Уходит с <span class=\"ch\" data-ch=\"tesey\">Тесеем</span>.)"],["sd","<span class=\"ch\" data-ch=\"amfitrion\">Амфитрион</span> уходит во дворец, и двери за ними затворяются."],["sp","Хор"],["dir","покидая сцену под следующие слова"],["v","И рыданий и скорби полны,",0,1430,0,0],["v","Мы, дряхлые старцы, уходим.",0,1431,0,0],["v","Тот, кого мы теряем теперь,",0,1432,0,0],["v","Был для нас самой верной опорой.",0,1433,0,0],["h1","Комментарий","comm"],["p","Дата постановки неизвестна. По стилистическим признакам, существенно отличающим «Геракла» как от трагедий 30-х годов («Алькеста», «Медея»), так и от поздних произведений Еврипида, большинство исследователей относит эту трагедию примерно к концу 20-х — началу 10-х годов."],["p","Геракл был не частым гостем на трагической сцене, хотя различные эпизоды его легендарной биографии были достаточно подробно разработаны в послегомеровском эпосе и хоровой лирике. Этим жанрам, о которых сохранились только косвенные свидетельства, было известно, в частности, и убийство Гераклом его детей от Мегары, совершенное им в ранней молодости в приступе безумия. Отнесение же этого события к последним годам жизни героя, равно как весь эпизод с участием Лика и вмешательство Тесея, принадлежит к собственным нововведениям Еврипида."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"]],"n":{"k1":["Ст. 4. …горсти земнородных…","Речь идет о спартах («посеянных») — героях, выросших на фиванской земле из зубов дракона, посеянных Кадмом (см.: «Финикиянки», ст. 638-675)."],"k2":["Ст. 15. Град киклопов.","Обычно так называли Микены, обнесенные в древности крепостной стеной «киклопической кладки» (см. сг. 944); в V в., после разрушения Микен соседним с ними Аргосом, на последний стали переносить легендарную характеристику Микен."],"k3":["Ст. 17. Электрион","тиринфский герой, дядя Амфитриона и отец Алкмены, случайно убитый Амфитрионом, который должен был поэтому уйти в изгнание. После этого власть над Аргосом захватил другой племянник Электриона — Еврисфей; в услужение ему кознями Геры и был отдан Геракл. Еврипид, вопреки традиции, изображает здесь дело таким образом (ст. 17-21), что Геракл добровольно пошел служить Еврисфею ради возвращения себе родины и престола."],"k4":["Ст. 23. Тенар","скалистый мыс с пещерой на юге Пелопоннеса, где греки локализовали один из входов в подземное царство."],"k5":["Ст. 27-34","Мифологическая генеалогия знала фиванского царя Лика, чья супруга Дирка (Диркея) всячески мучила свою племянницу Антиопу, мать божественных близнецов Амфиона и Зета; последние, выросши, отплатили Дирке за издевательства над их матерью, а Лика свергли с престола. О втором Лике и его вмешательстве в мятеж, якобы разгоревшийся в Фивах при Креонте, см. вступительную заметку к примечаниям."],"k6":["Ст. 50. Минийцы","обитатели соседнего с Фивами Орхомена, некогда властвовавшие над Фивами. Геракл пошел на них походом и освободил, таким образом, Фивы от рабской зависимости (ср ст. 220)."],"k7":["Ст. 63. …разрушить стены тафийские…","Когда Амфитрион был молод, на царство его дяди и тестя Электриона (см. ст. 17) напало войско Птерелая, царя острова Тафоса (ныне Меганион, расположен в восточной части Ионийского моря, у берегов Акарнании). В войне были убиты все сыновья Электриона, но Амфитрион, возглавив аргосскую рать, выступил против тафийцев и одержал над ними победу (см. также ст. 1080)."],"k8":["Ст. 177-180. …Гигантов поражал…","Мифологическая традиция приписывала Гераклу, наряду с другими подвигами, также участие в битве богов с Гигантами — сыновьями Земли."],"k9":["Ст. 188-205","Здесь, как и несколько выше (ст. 159-164), Еврипид принимает участие в споре между сторонниками ополчения тяжеловооруженных воинов (гоплитов) и их противниками, отдававшими предпочтение легковооруженным стрелкам из лука. В годы Пелопоннесской войны этот спор имел актуальное значение."],"k10":["Ст. 240. …другие на Парнас…","Этот приказ должен характеризовать сумасбродство тирана: от Фив до ближайших предгорий Парнаса — расстояние не менее 50 км."],"k11":["Ст. 252. Спарты","см. примеч. к ст. 4. Разумеется, зубы дракона посеял не сам Арей, а Кадм, одолевший чудовище, вскормленное Ареем. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 4. …горсти земнородных….</b> Речь идет о спартах («посеянных») — героях, выросших на фиванской земле из зубов дракона, посеянных Кадмом (см.: «Финикиянки», ст. 638-675).</span><!--/xn-->"],"k12":["Ст. 350. Смычком Аполлон ударяет…","Примечание Анненского: «Перевод неточен: »плектр« обозначает орудие, которым не водили по струнам, а щипали их, как на цитре»."],"k13":["Ст. 348-441","Хор вспоминает подвиги Геракла: борьбу с немейским львом («роща Кронида» — Немея с храмом Зевса); битву с кентаврами (Пеней — река в Фессалии, там же находится гора Пелион); охоту на керинейскую лань; укрощение коней Диомеда (см. примеч. к «Алькесте», ст. 65; Гебр — река во Фракии); единоборство с Кикном (см. примеч. к «Алькесте», 502 сл.); поход за золотыми яблоками в сад Гесперид (см. примеч. к «Ипполиту», ст. 732-751); сражение с амазонками, которых древнегреческая традиция локализовала обычно в приазовских степях (Меотида — Азовское море); убийство стоглавой лернейской гидры и трехтелого великана Гериона; наконец, поход в подземное царство за Кербером, на этот раз, как думает хор, с печальным исходом. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Алькеста», Ст. 65. …от Еврисфея муж… зайдет….</b> Геракл, отправляющийся за конями фракийского царя Диомеда (ст. 481 — 498); к этому эпизоду Еврипид приурочивает посещение Гераклом дома Адмета. Слова Аполлона (ст. 65 — 71) характерны для драматической техники Еврипида, любившего сообщать о развязке трагедии задолго до ее наступления.</span><!--/xn--> <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Алькеста», Ст. 502. Ликаон, Кикн..</b> Сражение Геракла с Ликаоном в других источниках не упоминается, единоборство же с Кикном составляет сюжет приписываемой Гесиоду поэмы «Щит Геракла». Ср. также «Геракл» Еврипида, ст. 389 сл.</span><!--/xn--> <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ипполит», Ст. 732-751.</b> В первой паре строф хор называет фантастические страны, куда бы он хотел укрыться от тягостей окружающей его действительности. Эридан — мифическая река, отождествляемая с Роной или По; в нее, по преданию, рухнул Фаэтон, сраженный молнией Зевса; его сестры («.Несчастные девы»}, превратившись в тополя, оплакивают его янтарными слезами. Сады Гесперид греки локализовали на Крайнем Западе, в районе нынешнего Гибралтара: здесь узкий пролив преграждает путь кораблям по воле морей промыслителя — Посейдона, здесь Атлант — мученик небодержавный — несет на плечах небесный свод, здесь бьет источник амбросии — пищи богов, и здесь же находилось ложе Кронида, когда он впервые соединился с Герой.</span><!--/xn-->"],"k14":["Ст. 442-450","Вступление в новую речевую сцену выдержано Еврипидом в традиционных для такого случая анапестических диметрах, которые не переданы переводчиком."],"k15":["Ст. 464. Пеласгия","здесь: аргосское царство."],"k16":["Ст. 471. …Дедалов дар, предательский гостинец…","Знаменитая палица Геракла названа в оригинале его «защитницей», которая на этот раз, однако, не сумела ему помочь; отсюда ее характеристика как «предательского гостинца»."],"k17":["Ст. 473. Ты… получал Эхалию…","См. примеч. к «Ипполиту», ст. 545-554. Поскольку в «Геракле» Еврипид приурочил безумие героя к концу его жизни, он не связывает здесь с взятием Эхалии никаких роковых для Геракла событий. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ипполит», Ст. 545 — 554.</b> Ярма не познавшая дева… — Иола, дочь эхалийского царя Еврита. Чтобы овладеть ею, Геракл захватил и разорил Эхалию и убил Еврита. Однако пленение Иолы послужило причиной мучительной смерти самого Геракла (см. «Трахинянки» Софокла).</span><!--/xn-->"],"k18":["Ст. 482. Парки","латинизм; в подлиннике — «Керы», богини смертного жребия."],"k19":["Ст. 579. …и красного дракона…","вольный перевод: речь идет о лернейской гидре."],"k20":["Ст. 588-592","Некоторыми учеными считались позднейшей публицистической вставкой в трагедию и пропущены Анненским; они переведены Ф. Ф. Зелинским."],"k21":["Ст. 596. …зловещий птичий знак…","См. примеч. к «Ипполиту», ст. 1058. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ипполит», Ст. 1058.</b> …птицы, в небесах… — По полету птиц специальные гадатели определяли будущее и угодность богам того или иного решения смертных.</span><!--/xn-->"],"k22":["Ст. 637-700","В словах этого хора, особенно в ст. 673 — 686, многие исследователи видят собственное высказывание Поэта, переступившего ко времени создания «Геракла» рубеж своего седьмого десятилетия."],"k23":["Ст. 747-748","пропущены Анненским и переведены Зелинским."],"k24":["Ст. 785. Асоп","река в Беотии."],"k25":["Ст. 800. …к Персеевой внуке…","Алкмене; ее отец Электрион (см. примеч. к ст. 17) — сын Персея. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 17. Электрион.</b> тиринфский герой, дядя Амфитриона и отец Алкмены, случайно убитый Амфитрионом, который должен был поэтому уйти в изгнание. После этого власть над Аргосом захватил другой племянник Электриона — Еврисфей; в услужение ему кознями Геры и был отдан Геракл. Еврипид, вопреки традиции, изображает здесь дело таким образом (ст. 17-21), что Геракл добровольно пошел служить Еврисфею ради возвращения себе родины и престола.</span><!--/xn-->"],"k26":["Ст. 822-842","Монолог Ириды носит все признаки еврипидовского пролога, чем подчеркивается формальная двухчастность этой трагедии, две половины которой соединены по контрастному принципу."],"k27":["Ст. 855-874","В сохранившихся трагедиях Еврипида это первый (в хронологическом отношении) пример употребления трохеического тетраметра (восьмистопного хорея с усечением последней стопы), предназначаемого для передачи сильного волнения или напряженного спора. Однако часто употребляемая переводчиком рифма не имеет соответствия в оригинале."],"k28":["Ст. 894. Бромий","ритуальный эпитет Диониса (Вакха), сопровождаемого толпой неистовствующих вакханок; их постоянные атрибуты — тирс (жезл, увитый плющом и виноградом) и тимпан (ударный инструмент, напоминающий бубен)."],"k29":["Ст. 926-930. …в ходу… была корзина…","Корзина, в которой хранились принадлежности для жертвоприношения, в том числе сосуд со священной водой; в нее погружали кусок угля с алтаря и при его помощи окропляли священной водой место для жертвоприношения и участников церемонии (см. ст. 928 сл.)."],"k30":["Ст. 1018. …мужей Данаиды убили…","См. примеч. к «Гекубе» (ст. 886 ел.). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гекуба», Ст. 886 сл.</b> Дети Египтовы, вынудившие к браку с ними своих двоюродных сестер, дочерей Даная, были все, кроме одного, убиты в брачную ночь Данаидами (см. трагедию Эсхила «Просительницы»). На Лемносе женщины умертвили своих неверных мужей.</span><!--/xn-->"],"k31":["Ст. 1031. Вот, вот они, дети…","Для показа событий, происходящих за пределами орхестры, в древнегреческом театре использовалось специальное приспособление, так называемая эккиклема — подвижная площадка, которая выкатывалась из центральных дверей сцены. На ней и располагались в нашей трагедии привязанный к обломку колонны Геракл и трупы убитых."],"k32":["Ст. 1163-1171","Появление Тесея не только хорошо мотивировано, но в его речи содержится также вполне понятный афинянам политический намек: границей между Аттикой и Беотией, где он оставил свое войско, Тесей считает реку Асоп, в то время как естественная граница между этими областями Греции проходила южнее, по горному хребту Киферону. Еврипид заставляет Тесея говорить так потому, что между Кифероном и Асопом лежала область платейцев, которые были союзниками афинян в Пелопоннесской войне и подверглись за это нападению беотийцев."],"k33":["Ст. 1178. …скалистого града оливы…","По преданию, на скалистой вершине Акрополя богиней Афиной было посажено первое оливковое дерево."],"k34":["Ст. 1188-1190","Стихи переведены Анненским по восстановлению Виламовица."],"k35":["Ст. 1243","Точнее: «Боги не считаются со мной, а я — с ними»."],"k36":["Ст. 1291-1293",", 1298-1299, 1338-1339 пропущены Анненским и переведены Зелинским."],"k37":["Ст. 1314-1321","Логика Тесея удивительным образом напоминает доводы кормилицы в «Ипполите» (ст. 456 сл.). Под поэтами, писавшими о «беззаконных браках» в небесах, Еврипид разумел скорее всего Гомера и Гесиода; бог, заковавший своего отца, — Зевс, поступивший так с Кроном."],"k38":["Ст. 1327. …дважды семь детей…","Имеются в виду семь афинских юношей и семь девушек, которых Тесей избавил от смерти, убив в лабиринте в Кносе Минотавра."],"k39":["Ст. 1324-1335","Приглашение Геракла в Афины и предлагаемые ему дары — новшество, введенное в миф Еврипидом и не оказавшее влияния на дальнейшую мифологическую традицию."],"k40":["Ст. 1403. Ты","ты верный… — После этой реплики, по мнению ряда исследователей, в рукописях выпал один стих, который Анненский дополняет по смыслу (Вперед! Я поделюсь с тобою счастьем)."]},"mainEnd":2216,"c":[{"id":"gerakl","name":"Геракл","role":"Сын Зевса и Алкмены","intro":"Величайший герой, вернувшийся из Аида, чтобы спасти семью, — и погубивший её.","arc":"Пьеса построена как резкий перелом: в первой половине Геракл — спаситель, который приходит в последний момент и убивает тирана Лика. Во второй Гера насылает на него безумие, и он убивает жену и детей. Очнувшись, он хочет умереть, но Тесей убеждает его жить: мужество теперь — вынести своё несчастье. Еврипидов Геракл отвергает рассказы о порочных богах и принимает человеческую дружбу как последнюю опору.","st":[{"i":917,"p":41,"l":"Действие второе · явление седьмое","t":"Возвращение","d":"Неожиданно является из Аида, узнаёт об угрозе семье и решает расправиться с Ликом.","c":"Спаситель приходит вовремя.","k":true},{"i":1098,"p":50,"l":"Действие третье · явление девятое","t":"Смерть Лика","d":"Из дворца раздаются крики убиваемого тирана.","c":"","k":false},{"i":1487,"p":67,"l":"Действие четвертое · явление двенадцатое","t":"Безумие","d":"Вестник рассказывает: охваченный Лиссой, Геракл принял детей за детей Еврисфея и убил их и Мегару.","c":"Высшая точка падения.","k":false},{"i":1764,"p":80,"l":"Исход · явление тринадцатое","t":"Пробуждение","d":"Связанный, приходит в себя среди трупов и узнаёт, что сделал. Хочет умереть.","c":"","k":false},{"i":2215,"p":100,"l":"Исход · явление четырнадцатое","t":"Решение жить","d":"Тесей не боится скверны, обнимает друга и зовёт его в Афины. Геракл отказывается от самоубийства.","c":"Мужество — в том, чтобы вынести несчастье.","k":true}],"gen":"Геракл"},{"id":"amfitrion","name":"Амфитрион","role":"Земной отец Геракла","intro":"Старик, защищающий семью сына в его отсутствие.","arc":"Амфитрион — голос надежды в первой части: он ищет отсрочки, верит в возвращение сына. Во второй — свидетель ужаса, который должен рассказать Гераклу правду.","st":[{"i":151,"p":7,"l":"Пролог · явление первое","t":"У алтаря","d":"Вместе с Мегарой и внуками ищет защиты у алтаря Зевса от Лика.","c":"","k":false},{"i":457,"p":21,"l":"Действие первое · явление третье","t":"Спор с Ликом","d":"Защищает честь Геракла от насмешек тирана.","c":"","k":false},{"i":1038,"p":47,"l":"Действие третье · явление восьмое","t":"Западня","d":"Заманивает Лика во дворец, где его ждёт Геракл.","c":"","k":true},{"i":1764,"p":80,"l":"Исход · явление тринадцатое","t":"Правда","d":"Открывает очнувшемуся Гераклу, что тот убил детей.","c":"","k":false}],"gen":"Амфитрион"},{"id":"megara","name":"Мегара","role":"Жена Геракла, дочь Креонта","intro":"Жена, готовая с достоинством принять смерть вместе с детьми.","arc":"Мегара трезвее Амфитриона: она не верит в возвращение мужа и просит лишь о достойной смерти. Её спасение длится недолго.","st":[{"i":464,"p":21,"l":"Действие первое · явление четвертое","t":"Принять смерть","d":"Просит позволить ей одеть детей в погребальные одежды.","c":"","k":true},{"i":917,"p":41,"l":"Действие второе · явление седьмое","t":"Встреча с мужем","d":"Видит Геракла живым и рассказывает о Лике.","c":"","k":false},{"i":1487,"p":67,"l":"Действие четвертое · явление двенадцатое","t":"Гибель","d":"Убита мужем в припадке безумия.","c":"","k":false}],"gen":"Мегара"},{"id":"lik","name":"Лик","role":"Узурпатор фиванского престола","intro":"Тиран, решивший истребить семью Геракла.","arc":"Лик убил Креонта и боится, что сыновья Геракла отомстят. Он насмехается над Гераклом и в итоге сам попадает в его руки.","st":[{"i":457,"p":21,"l":"Действие первое · явление третье","t":"Угроза","d":"Насмехается над Гераклом и грозит сжечь семью у алтаря.","c":"","k":true},{"i":1098,"p":50,"l":"Действие третье · явление девятое","t":"Смерть","d":"Входит во дворец и погибает.","c":"","k":false}]},{"id":"tesey","name":"Тесей","role":"Царь Афин","intro":"Друг, спасённый Гераклом из Аида.","arc":"Тесей приходит отплатить за спасение и становится опорой Геракла, отказывающегося жить.","st":[{"i":2215,"p":100,"l":"Исход · явление четырнадцатое","t":"Дружба","d":"Не страшась скверны, уговаривает Геракла жить и увозит его в Афины.","c":"","k":true}],"gen":"Тесей"}]};
